			DuelSettings settings = DuelSettings.GetSettings();
			if (settings != null)
			{
				return MBMath.ClampInt(settings.MemorySummaryRequestsPerMinute, 1, 20);
			}
		}
		catch
		{
		}
		return 3;
	}

