	private static int GetMemoryCandidateLimitFromSettings()
	{
		try
		{
			DuelSettings settings = DuelSettings.GetSettings();
			if (settings != null)
			{
				return MBMath.ClampInt(settings.MemoryCandidateLimit, 5, 40);
