	private void OnGovernorChangedForActionHistory(Town fortification, Hero oldGovernor, Hero newGovernor)
	{
		try
		{
			Settlement settlement = fortification?.Settlement;
			if (settlement == null || !IsPlayerRelatedGovernorChange(settlement, oldGovernor, newGovernor))
			{
				return;
			}
			string settlementName = GetSettlementDisplayName(settlement);
			string stablePrefix = "governor_changed:" + GetSettlementId(settlement) + ":" + GetCurrentGameDayIndexSafe();
			if (oldGovernor != null && oldGovernor != newGovernor)
			{
				string oldName = GetHeroDisplayName(oldGovernor);
				RecordExternalNpcAction(oldGovernor, "你卸任了" + settlementName + "总督。", stablePrefix + ":removed:" + GetHeroId(oldGovernor), "governor_removed", isMajor: true, isRecent: true, targetHero: Hero.MainHero, settlement: settlement, locationText: settlementName, allowNonLordHero: true, won: null);
				RecordExternalPlayerAction("你解除了" + oldName + "的" + settlementName + "总督职务。", stablePrefix + ":player_removed:" + GetHeroId(oldGovernor), "governor_removed", isMajor: true, targetHero: oldGovernor, settlement: settlement, locationText: settlementName, won: null);
			}
			if (newGovernor != null)
			{
				string newName = GetHeroDisplayName(newGovernor);
				RecordExternalNpcAction(newGovernor, "你被任命为" + settlementName + "总督。", stablePrefix + ":appointed:" + GetHeroId(newGovernor), "governor_appointed", isMajor: true, isRecent: true, targetHero: Hero.MainHero, settlement: settlement, locationText: settlementName, allowNonLordHero: true, won: true);
				RecordExternalPlayerAction("你任命了" + newName + "担任" + settlementName + "总督。", stablePrefix + ":player_appointed:" + GetHeroId(newGovernor), "governor_appointed", isMajor: true, targetHero: newGovernor, settlement: settlement, locationText: settlementName, won: true);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("NpcAction", "[ERROR] OnGovernorChangedForActionHistory: " + ex.Message);
		}
	}

	private void RecordNpcDefeatedByPlayerRecentAction(MapEvent mapEvent, MapEventSide defeatedSide, Hero defeatedHero)
	{
		if (mapEvent == null || defeatedHero == null || defeatedHero == Hero.MainHero || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide != mapEvent.PlayerSide)
		{
			return;
		}
		defeatedSide ??= GetMapEventDefeatedSide(mapEvent);
		if (defeatedSide == null || !ShouldTrackNpcActionHero(defeatedHero))
		{
			return;
		}
		string locationLabel = GetMapEventLocationLabel(mapEvent);
		string text = BuildNpcDefeatedByPlayerRecentActionText(mapEvent, defeatedSide, locationLabel);
		string stableKey = BuildMapEventParticipantStableKey(mapEvent, defeatedSide, defeatedHero, locationLabel);
		bool isMajor = ShouldRecordMajorBattleAction(GetMapEventTroopCount(mapEvent));
		RecordExternalNpcAction(defeatedHero, text, stableKey, "map_event", isMajor, isRecent: true, targetHero: Hero.MainHero, settlement: mapEvent.MapEventSettlement, locationText: locationLabel, allowNonLordHero: false, won: false);
	}

	private void RecordPlayerBattleDefeatRecentAction(MapEvent mapEvent)
	{
		if (mapEvent == null || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide == mapEvent.PlayerSide || Hero.MainHero == null)
		{
			return;
		}
		MapEventSide playerSide = GetMapEventSideByBattleSide(mapEvent, mapEvent.PlayerSide);
		if (playerSide == null)
		{
			return;
		}
		string locationLabel = GetMapEventLocationLabel(mapEvent);
		string text = BuildPlayerBattleDefeatRecentActionText(mapEvent, playerSide, locationLabel);
		string stableKey = BuildMapEventParticipantStableKey(mapEvent, playerSide, Hero.MainHero, locationLabel);
		Hero targetHero = playerSide.OtherSide?.LeaderParty?.LeaderHero;
		bool isMajor = ShouldRecordMajorBattleAction(GetMapEventTroopCount(mapEvent));
		RecordExternalPlayerAction(text, stableKey, "map_event", isMajor, targetHero, mapEvent.MapEventSettlement, locationLabel, won: false);
	}

	private static string BuildMapEventParticipantStableKey(MapEvent mapEvent, MapEventSide side, Hero hero, string locationLabel)
	{
		string mapEventStableKey = BuildMapEventStableKey(mapEvent, locationLabel);
		return mapEventStableKey + ":side:" + side?.MissionSide + ":hero:" + (hero?.StringId ?? "");
	}

	private static string BuildPlayerDefeatedHeroBattleFactKey(MapEvent mapEvent, MapEventSide defeatedSide, Hero defeatedHero, string locationLabel)
	{
		List<string> list = new List<string>
		{
			"player_defeated_hero_fact",
			GetCurrentGameDayIndexSafe().ToString(),
			NormalizeWeeklyPromptKeyPart(mapEvent?.StringId),
			NormalizeWeeklyPromptKeyPart(locationLabel),
			NormalizeWeeklyPromptKeyPart(mapEvent == null ? "" : mapEvent.PlayerSide.ToString()),
			NormalizeWeeklyPromptKeyPart(defeatedSide == null ? "" : defeatedSide.MissionSide.ToString()),
			GetHeroId(defeatedHero),
			GetHeroId(defeatedSide?.LeaderParty?.LeaderHero),
			GetHeroId(defeatedSide?.OtherSide?.LeaderParty?.LeaderHero),
			NormalizeWeeklyPromptKeyPart(BuildMapEventStableKey(mapEvent, locationLabel))
		};
		return string.Join(":", list.Where((string x) => !string.IsNullOrWhiteSpace(x)));
	}

	private bool HasRecordedPlayerDefeatedHeroBattleFact(MapEvent mapEvent, MapEventSide defeatedSide, Hero defeatedHero)
	{
		if (mapEvent == null || defeatedSide == null || defeatedHero == null)
		{
			return false;
		}
		string locationLabel = GetMapEventLocationLabel(mapEvent);
		string stableKey = BuildPlayerDefeatedHeroBattleFactKey(mapEvent, defeatedSide, defeatedHero, locationLabel);
		return !string.IsNullOrWhiteSpace(stableKey) && _playerDefeatedHeroBattleFactKeys.Contains(stableKey);
	}

	private static MapEventSide GetMapEventSideByBattleSide(MapEvent mapEvent, BattleSideEnum side)
	{
		if (mapEvent == null)
		{
			return null;
		}
		if (side == BattleSideEnum.Attacker)
		{
			return mapEvent.AttackerSide;
		}
		if (side == BattleSideEnum.Defender)
		{
			return mapEvent.DefenderSide;
		}
		return null;
	}

	private static string BuildPlayerDefeatedHeroDialogueFact(MapEvent mapEvent, MapEventSide defeatedSide, string locationLabel)
	{
		string playerName = Hero.MainHero?.Name?.ToString()?.Trim();
		if (string.IsNullOrWhiteSpace(playerName))
		{
			playerName = "玩家";
		}
		string place = string.IsNullOrWhiteSpace(locationLabel) ? "野外" : locationLabel.Trim();
		string battleKind = "战斗";
		if (mapEvent?.IsSiegeAssault == true || mapEvent?.IsSiegeOutside == true || mapEvent?.IsSallyOut == true)
		{
			battleKind = "攻守战";
		}
		else if (mapEvent?.IsRaid == true)
		{
			battleKind = "袭掠战";
		}
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.Append("[AFEF玩家行为补充] 你刚在").Append(place).Append("的").Append(battleKind).Append("中被").Append(playerName).Append("一方击败；这场战败已经发生。");
		string winningLords = BuildTrackedHeroListText(defeatedSide?.OtherSide, 4);
		if (!string.IsNullOrWhiteSpace(winningLords))
		{
			stringBuilder.Append(" 胜方主要领主：").Append(winningLords).Append('。');
		}
		return stringBuilder.ToString();
	}

	private static string BuildNpcDefeatedByPlayerRecentActionText(MapEvent mapEvent, MapEventSide defeatedSide, string locationLabel)
	{
		string playerName = Hero.MainHero?.Name?.ToString()?.Trim();
		if (string.IsNullOrWhiteSpace(playerName))
		{
			playerName = "玩家";
		}
		StringBuilder stringBuilder = new StringBuilder();
		if (mapEvent?.IsSiegeAssault == true || mapEvent?.IsSiegeOutside == true || mapEvent?.IsSallyOut == true)
		{
			stringBuilder.Append("你在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "某处要塞" : locationLabel.Trim()).Append("的攻守战中被").Append(playerName).Append("一方击败。");
		}
		else if (mapEvent?.IsRaid == true)
		{
			stringBuilder.Append("你在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "某处村庄" : locationLabel.Trim()).Append("的袭掠战中被").Append(playerName).Append("一方击败。");
		}
		else
		{
			stringBuilder.Append("你在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "野外" : locationLabel.Trim()).Append("的战斗中被").Append(playerName).Append("一方击败。");
		}
		AppendBattleOpponentDetails(stringBuilder, defeatedSide?.OtherSide, "胜方");
		AppendBattleCasualtyDetails(stringBuilder, defeatedSide, defeatedSide?.OtherSide);
		return stringBuilder.ToString();
	}

	private static string BuildPlayerBattleDefeatRecentActionText(MapEvent mapEvent, MapEventSide playerSide, string locationLabel)
	{
		string opponentLabel = BuildMapEventSideNarrativeLabel(playerSide?.OtherSide);
		if (string.IsNullOrWhiteSpace(opponentLabel))
		{
			opponentLabel = "敌军";
		}
		StringBuilder stringBuilder = new StringBuilder();
		if (mapEvent?.IsSiegeAssault == true || mapEvent?.IsSiegeOutside == true || mapEvent?.IsSallyOut == true)
		{
			stringBuilder.Append("玩家在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "某处要塞" : locationLabel.Trim()).Append("的攻守战中败给了").Append(opponentLabel).Append("。");
		}
		else if (mapEvent?.IsRaid == true)
		{
			stringBuilder.Append("玩家在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "某处村庄" : locationLabel.Trim()).Append("的袭掠战中败给了").Append(opponentLabel).Append("。");
		}
		else
		{
			stringBuilder.Append("玩家在").Append(string.IsNullOrWhiteSpace(locationLabel) ? "野外" : locationLabel.Trim()).Append("的战斗中败给了").Append(opponentLabel).Append("。");
		}
		AppendBattleOpponentDetails(stringBuilder, playerSide?.OtherSide, "胜方");
		AppendBattleCasualtyDetails(stringBuilder, playerSide, playerSide?.OtherSide);
		return stringBuilder.ToString();
	}

	private static void AppendBattleOpponentDetails(StringBuilder stringBuilder, MapEventSide opponentSide, string label)
	{
		if (stringBuilder == null || opponentSide == null)
		{
			return;
		}
		string sideLabel = string.IsNullOrWhiteSpace(label) ? "对方" : label.Trim();
		string lords = BuildTrackedHeroListText(opponentSide, 6);
		if (!string.IsNullOrWhiteSpace(lords))
		{
			stringBuilder.Append(' ').Append(sideLabel).Append("领主：").Append(lords).Append('。');
		}
		string nonLordParties = BuildMapEventNonLordPartyListText(opponentSide, 5);
		if (!string.IsNullOrWhiteSpace(nonLordParties))
		{
			stringBuilder.Append(' ').Append(sideLabel).Append("非领主部队：").Append(nonLordParties).Append('。');
		}
	}

	private static void AppendBattleCasualtyDetails(StringBuilder stringBuilder, MapEventSide defeatedSide, MapEventSide winningSide)
	{
		if (stringBuilder == null)
		{
			return;
		}
		string defeatedCasualties = BuildMapEventCasualtyText(defeatedSide);
		string winningCasualties = BuildMapEventCasualtyText(winningSide);
		if (!string.IsNullOrWhiteSpace(defeatedCasualties) || !string.IsNullOrWhiteSpace(winningCasualties))
		{
			stringBuilder.Append(" 败方死伤：").Append(string.IsNullOrWhiteSpace(defeatedCasualties) ? "不详" : defeatedCasualties);
			stringBuilder.Append("；胜方死伤：").Append(string.IsNullOrWhiteSpace(winningCasualties) ? "不详" : winningCasualties).Append('。');
		}
	}

	private void RecordPlayerHideoutClearRecentAction(MapEvent mapEvent)
	{
		if (mapEvent == null || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide != mapEvent.PlayerSide || !mapEvent.IsHideoutBattle)
		{
			return;
		}
		Settlement settlement = mapEvent.MapEventSettlement;
		string settlementName = GetSettlementDisplayName(settlement);
		if (string.IsNullOrWhiteSpace(settlementName))
		{
			settlementName = "一处藏身处";
		}
		string text = "你清剿了" + settlementName + "，击败了盘踞其中的匪帮。";
		string stableKey = "hideout_cleared:" + (GetSettlementId(settlement) ?? "") + ":" + GetCurrentGameDayIndexSafe();
		RecordExternalPlayerAction(text, stableKey, "hideout_cleared", isMajor: false, targetHero: null, settlement: settlement, locationText: settlementName, won: true);
	}

	private void RecordPlayerRoutineBanditDefeatRecentAction(MapEvent mapEvent)
	{
		if (mapEvent == null || !mapEvent.IsPlayerMapEvent || !mapEvent.HasWinner || mapEvent.WinningSide != mapEvent.PlayerSide || mapEvent.IsHideoutBattle)
		{
			return;
		}
		if (!ShouldSkipRoutineBanditDefeatMapEvent(mapEvent))
		{
			return;
		}
		MapEventSide defeatedSide = GetMapEventDefeatedSide(mapEvent);
		if (defeatedSide == null)
		{
			return;
		}
		string locationLabel = GetMapEventLocationLabel(mapEvent);
		string enemyLabel = GetPrimaryOtherSideLabel(defeatedSide);
		if (string.IsNullOrWhiteSpace(enemyLabel) || string.Equals(enemyLabel, "敌军", StringComparison.OrdinalIgnoreCase))
		{
			enemyLabel = "一支野外匪帮";
		}
		int enemyCount = GetMapEventSideCommittedTroopCount(defeatedSide);
		StringBuilder stringBuilder = new StringBuilder();
		if (string.Equals(locationLabel, "野外", StringComparison.Ordinal))
		{
			stringBuilder.Append("你在野外击败了").Append(enemyLabel).Append("，取得了一场小规模遭遇战胜利。");
		}
		else
		{
			stringBuilder.Append("你在").Append(locationLabel).Append("附近击败了").Append(enemyLabel).Append("，取得了一场小规模遭遇战胜利。");
		}
		if (enemyCount > 0)
		{
			stringBuilder.Append(" 敌方投入约").Append(enemyCount).Append("人。");
		}
		if (GetMapEventSideCasualtyCount(defeatedSide) > 0)
		{
			stringBuilder.Append(" 敌方").Append(BuildMapEventCasualtyText(defeatedSide)).Append("。");
		}
		string stableKey = BuildRoutineBanditDefeatStableKey(mapEvent, defeatedSide, locationLabel);
		RecordExternalPlayerAction(stringBuilder.ToString(), stableKey, "wild_party_defeated", isMajor: false, targetHero: null, settlement: mapEvent.MapEventSettlement, locationText: locationLabel, won: true);
	}

	private void RecordExternalNpcAction(Hero actorHero, string text, string stableKey, string actionKind, bool isMajor, bool isRecent, Hero targetHero, Settlement settlement, string locationText, bool allowNonLordHero, bool? won)
	{
		if (!ShouldTrackNpcActionHero(actorHero, allowNonLordHero))
		{
			return;
		}
		string cleanText = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (string.IsNullOrWhiteSpace(cleanText))
		{
			return;
		}
		NpcActionFacts facts = CreateNpcActionFacts(actionKind, actorHero);
		ApplyTargetFacts(facts, targetHero);
		if (settlement != null)
		{
			ApplySettlementFacts(facts, settlement, null, null, locationText);
			AddRelatedFactionFacts(facts, settlement.MapFaction);
		}
		else
		{
			facts.LocationText = (locationText ?? "").Trim();
		}
		facts.Won = won;
		string key = string.IsNullOrWhiteSpace(stableKey) ? BuildExternalActionStableKey(actionKind, actorHero, targetHero, cleanText) : stableKey.Trim();
		if (isMajor)
		{
			RecordNpcMajorAction(actorHero, cleanText, key, facts, allowNonLordHero);
		}
		if (isRecent)
		{
			RecordNpcRecentAction(actorHero, cleanText, key, dedupeAcrossWindow: true, facts, allowNonLordHero);
		}
	}

	private void RecordExternalPlayerAction(string text, string stableKey, string actionKind, bool isMajor, Hero targetHero, Settlement settlement, string locationText, bool? won)
	{
		string cleanText = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
		if (string.IsNullOrWhiteSpace(cleanText))
		{
			return;
		}
		Hero player = Hero.MainHero;
		int day = GetCurrentGameDayIndexSafe();
		string key = string.IsNullOrWhiteSpace(stableKey) ? BuildExternalActionStableKey(actionKind, player, targetHero, cleanText) : stableKey.Trim();
		PlayerNotorietyBehavior.RecordPlayerActionForExternal(
			cleanText,
			key,
			(actionKind ?? "").Trim(),
			isMajor,
			day,
			GetCurrentGameDateTextSafe(),
			++_npcActionGlobalOrderCounter,
			GetSettlementId(settlement),
			GetSettlementDisplayName(settlement),
			(locationText ?? GetSettlementDisplayName(settlement)).Trim(),
			player?.Culture?.StringId ?? "",
			targetHero?.Culture?.StringId ?? "",
			settlement?.Culture?.StringId ?? "",
			won);
	}

	private void RecordExternalPlayerHighValueRpCraft(
		string batchId,
		string requestedName,
		string finalDisplayName,
		int investedDenars,
		int craftedItemValue,
		string crafterHeroId,
		string crafterDisplayName,
		string outcomeLabel)
	{
		if (investedDenars <= 10000)
		{
			return;
		}
		string normalizedBatchId = (batchId ?? "").Trim();
		string requested = LimitCustomPolicyWeeklyMaterialText(
			requestedName,
			80);
		string finalName = LimitCustomPolicyWeeklyMaterialText(
			finalDisplayName,
			80);
		if (string.IsNullOrWhiteSpace(normalizedBatchId)
			|| string.IsNullOrWhiteSpace(requested)
			|| string.IsNullOrWhiteSpace(finalName))
		{
			return;
		}
		string crafterName = LimitCustomPolicyWeeklyMaterialText(
			crafterDisplayName,
			60);
		string result = LimitCustomPolicyWeeklyMaterialText(
			outcomeLabel,
			40);
		Hero player = Hero.MainHero;
		bool craftedByPlayer = string.Equals(
			(crafterHeroId ?? "").Trim(),
			GetHeroId(player),
			StringComparison.OrdinalIgnoreCase);
		string investment = investedDenars.ToString(
			CultureInfo.InvariantCulture);
		string outputValue = Math.Max(1, craftedItemValue).ToString(
			CultureInfo.InvariantCulture);
		bool renamedByOutcome = !string.Equals(
			requested,
			finalName,
			StringComparison.Ordinal);
		string actionText = craftedByPlayer
			? "你投入 " + investment + " 第纳尔，亲手制造"
			: "你投入 " + investment + " 第纳尔，并委托 "
				+ (string.IsNullOrWhiteSpace(crafterName)
					? "一名家族成员或同伴"
					: crafterName)
				+ " 制造";
		actionText += renamedByOutcome
			? "“" + requested + "”，最终得到“" + finalName + "”"
			: "了“" + finalName + "”";
		actionText += "；成品价值 " + outputValue + " 第纳尔"
			+ (string.IsNullOrWhiteSpace(result)
				? "。"
				: "，制造结果为" + result + "。");

		string stableKey =
			"player_rp_craft_high_value:" + normalizedBatchId;
		Settlement settlement =
			Settlement.CurrentSettlement
			?? MobileParty.MainParty?.CurrentSettlement;
		string locationText =
			GetSettlementDisplayName(settlement);
		if (string.IsNullOrWhiteSpace(locationText))
		{
			locationText = "旅途中";
		}
		RecordExternalPlayerAction(
			actionText,
			stableKey + ":action",
			"player_rp_craft",
			isMajor: true,
			targetHero: null,
			settlement: settlement,
			locationText: locationText,
			won: null);

		bool hasKingdom =
			ResolvePlayerFootholdKingdomForWeeklyMemoryMaterial(
				out string kingdomId,
				out string settlementId);
		if (string.IsNullOrWhiteSpace(settlementId))
		{
			settlementId = GetSettlementId(settlement);
		}
		string weeklySnapshot = craftedByPlayer
			? "玩家投入 " + investment + " 第纳尔亲手制造"
			: "玩家投入 " + investment + " 第纳尔，委托 "
				+ (string.IsNullOrWhiteSpace(crafterName)
					? "一名家族成员或同伴"
					: crafterName)
				+ " 制造";
		weeklySnapshot += renamedByOutcome
			? "“" + requested + "”，最终得到“" + finalName + "”"
			: "了“" + finalName + "”";
		weeklySnapshot += "；成品价值 " + outputValue + " 第纳尔"
			+ (string.IsNullOrWhiteSpace(result)
				? "。"
				: "，制造结果为" + result + "。");
		RecordEventSourceMaterial(
			"player_rp_craft",
			"贵重物品制造 - " + finalName,
			weeklySnapshot,
			stableKey + ":weekly",
			kingdomId,
			settlementId,
			includeInWorld: true,
			includeInKingdom: hasKingdom,
			actorHeroId: GetHeroId(player),
			actorKingdomId: GetKingdomId(player?.MapFaction));
		Logger.Log(
			"EventWeeklyReport",
			"[PlayerRpCraft] high_value_material_recorded item="
				+ finalName
				+ " invested="
				+ investment
				+ " kingdom="
				+ (kingdomId ?? ""));
	}

	private void RecordVoteDealFulfilled(Hero npc, KingdomDecision decision, DecisionOutcome chosenOutcome, string dealId, string targetDecisionTitle, string targetOptionTitle)
	{
		if (npc == null || npc == Hero.MainHero)
		{
			return;
		}
		string decisionTitle = CleanExternalActionTitle(targetDecisionTitle);
		if (string.IsNullOrWhiteSpace(decisionTitle))
		{
			try
			{
				decisionTitle = CleanExternalActionTitle(decision?.GetGeneralTitle()?.ToString());
			}
			catch
			{
				decisionTitle = "";
			}
		}
		if (string.IsNullOrWhiteSpace(decisionTitle))
		{
			decisionTitle = "一项王国决议";
		}
		string optionTitle = CleanExternalActionTitle(targetOptionTitle);
		if (string.IsNullOrWhiteSpace(optionTitle))
		{
			try
			{
				optionTitle = CleanExternalActionTitle(chosenOutcome?.GetDecisionTitle()?.ToString());
			}
			catch
			{
				optionTitle = "";
			}
		}
		string optionPhrase = string.IsNullOrWhiteSpace(optionTitle) ? "" : ("，支持“" + optionTitle + "”");
		string stableKey = "vote_deal_fulfilled:" + ((dealId ?? "").Trim()) + ":" + GetHeroId(npc) + ":" + NormalizeWeeklyPromptKeyPart(decisionTitle);
		string npcText = "你履行了与玩家达成的投票交易，在“" + decisionTitle + "”中按承诺投票" + optionPhrase + "。";
		string playerText = "你促成" + GetHeroDisplayName(npc) + "履行投票交易，在“" + decisionTitle + "”中按承诺投票" + optionPhrase + "。";
		RecordExternalNpcAction(npc, npcText, stableKey + ":npc", "vote_deal_fulfilled", isMajor: true, isRecent: true, targetHero: Hero.MainHero, settlement: null, locationText: GetKingdomDisplayName(decision?.Kingdom, ""), allowNonLordHero: false, won: true);
		RecordExternalPlayerAction(playerText, stableKey + ":player", "vote_deal_fulfilled", isMajor: true, targetHero: npc, settlement: null, locationText: GetKingdomDisplayName(decision?.Kingdom, ""), won: true);
	}

	private static string BuildExternalActionStableKey(string actionKind, Hero actorHero, Hero targetHero, string text)
	{
		return "external_action:" + NormalizeWeeklyPromptKeyPart(actionKind) + ":" + GetHeroId(actorHero) + ":" + GetHeroId(targetHero) + ":" + GetCurrentGameDayIndexSafe() + ":" + NormalizeWeeklyPromptKeyPart((text ?? "").Length > 80 ? text.Substring(0, 80) : text);
	}

	private static Settlement ResolveQuestActionSettlement(Hero questGiver)
	{
		return ResolveCurrentActionSettlement(questGiver);
	}

	private static Settlement ResolveCurrentActionSettlement(Hero hero)
	{
		try
		{
			return Settlement.CurrentSettlement ?? PlayerEncounter.EncounterSettlement ?? MobileParty.MainParty?.CurrentSettlement ?? hero?.CurrentSettlement ?? hero?.StayingInSettlement ?? hero?.HomeSettlement;
		}
		catch
		{
			return null;
		}
	}

	private static bool IsPlayerRelatedGovernorChange(Settlement settlement, Hero oldGovernor, Hero newGovernor)
	{
		try
		{
			return settlement?.OwnerClan == Clan.PlayerClan || oldGovernor?.Clan == Clan.PlayerClan || newGovernor?.Clan == Clan.PlayerClan;
		}
		catch
		{
			return false;
		}
	}

	private static string CleanExternalActionTitle(string value)
	{
		return (value ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
	}

	private static string GetQuestCompletionActionKind(QuestBase.QuestCompleteDetails detail)
	{
		switch (detail)
		{
		case QuestBase.QuestCompleteDetails.Success:
			return "quest_success";
		case QuestBase.QuestCompleteDetails.Timeout:
			return "quest_timeout";
		case QuestBase.QuestCompleteDetails.FailWithBetrayal:
			return "quest_betrayal";
		case QuestBase.QuestCompleteDetails.Fail:
			return "quest_fail";
		case QuestBase.QuestCompleteDetails.Cancel:
			return "quest_cancel";
		default:
			return "quest_result";
		}
	}

	private static string GetQuestCompletionDetailLabel(QuestBase.QuestCompleteDetails detail)
	{
		switch (detail)
		{
		case QuestBase.QuestCompleteDetails.Success:
			return "成功完成";
		case QuestBase.QuestCompleteDetails.Fail:
			return "任务失败";
		case QuestBase.QuestCompleteDetails.FailWithBetrayal:
			return "以背叛结局失败";
		case QuestBase.QuestCompleteDetails.Timeout:
			return "超时结束";
		case QuestBase.QuestCompleteDetails.Cancel:
			return "已取消";
		default:
			return detail.ToString();
		}
	}

	private static string GetCompanionRemovedDetailLabel(RemoveCompanionAction.RemoveCompanionDetail detail)
	{
		return detail == RemoveCompanionAction.RemoveCompanionDetail.Fire ? "被遣散" : detail.ToString();
	}

	private void OnHeroPrisonerTaken(PartyBase capturer, Hero prisoner)
	{
		try
		{
			Hero hero = capturer?.LeaderHero ?? capturer?.MobileParty?.LeaderHero;
			Settlement settlement = ResolveSettlementForPartyBase(capturer);
			string text = GetLocationLabelForPartyBase(capturer);
			string text2 = BuildPrisonerTakenStableKey(hero, prisoner);
			if (ShouldTrackNpcActionHero(hero))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("prisoner_taken_captor", hero);
				npcActionFacts.LocationText = text;
				ApplySettlementFacts(npcActionFacts, settlement, locationText: text);
				ApplyTargetFacts(npcActionFacts, prisoner);
				if (prisoner?.MapFaction != null)
				{
					AddRelatedFactionFacts(npcActionFacts, prisoner.MapFaction);
				}
				string text3 = "你俘虏了" + GetHeroDisplayName(prisoner) + "。";
				RecordNpcMajorAction(hero, text3, text2 + ":captor", npcActionFacts);
				RecordNpcRecentAction(hero, text3, text2 + ":captor", facts: npcActionFacts);
			}
			if (ShouldTrackNpcActionHero(prisoner))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("prisoner_taken_prisoner", prisoner);
				npcActionFacts2.LocationText = text;
				ApplySettlementFacts(npcActionFacts2, settlement, locationText: text);
				if (hero != null)
				{
					ApplyTargetFacts(npcActionFacts2, hero);
				}
				else if (capturer?.MobileParty?.MapFaction != null)
				{
					AddRelatedFactionFacts(npcActionFacts2, capturer.MobileParty.MapFaction);
				}
				string text4 = ((hero != null) ? ("你被" + GetHeroDisplayName(hero) + "俘虏了。") : "你被敌方俘虏了。");
				RecordNpcMajorAction(prisoner, text4, text2 + ":prisoner", npcActionFacts2);
				RecordNpcRecentAction(prisoner, text4, text2 + ":prisoner", facts: npcActionFacts2);
			}
			if (prisoner != null && prisoner != Hero.MainHero && prisoner.IsLord && (capturer?.LeaderHero == Hero.MainHero || capturer?.MobileParty?.ActualClan == Clan.PlayerClan))
			{
				Logger.Log("BattleStatus", $"NPC {prisoner.Name} 被玩家俘虏");
				AppendExternalDialogueHistory(prisoner, null, null, $"你被 {Hero.MainHero.Name} 俘虏了，你现在是他的囚犯。");
			}
		}
		catch (Exception ex)
		{
			Logger.Log("BattleStatus", "[ERROR] OnHeroPrisonerTaken: " + ex.Message);
		}
	}

	private void OnHeroPrisonerReleased(Hero prisoner, PartyBase party, IFaction capturerFaction, EndCaptivityDetail detail, bool showNotification)
	{
		try
		{
			Hero hero = party?.LeaderHero ?? party?.MobileParty?.LeaderHero;
			Settlement settlement = ResolveSettlementForPartyBase(party);
			string text = GetLocationLabelForPartyBase(party);
			string text2 = BuildPrisonerReleasedStableKey(hero, prisoner, detail);
			string endCaptivityDetailLabel = GetEndCaptivityDetailLabel(detail);
			if (ShouldTrackNpcActionHero(prisoner))
			{
				NpcActionFacts npcActionFacts = CreateNpcActionFacts("prisoner_released_prisoner", prisoner);
				npcActionFacts.LocationText = text;
				ApplySettlementFacts(npcActionFacts, settlement, locationText: text);
				if (hero != null)
				{
					ApplyTargetFacts(npcActionFacts, hero);
				}
				else
				{
					AddRelatedFactionFacts(npcActionFacts, capturerFaction);
				}
				string text3 = string.IsNullOrWhiteSpace(endCaptivityDetailLabel) ? "你结束了囚禁状态。" : ("你" + endCaptivityDetailLabel + "并恢复了自由。");
				RecordNpcMajorAction(prisoner, text3, text2 + ":prisoner", npcActionFacts);
				RecordNpcRecentAction(prisoner, text3, text2 + ":prisoner", facts: npcActionFacts);
			}
			if (ShouldTrackNpcActionHero(hero))
			{
				NpcActionFacts npcActionFacts2 = CreateNpcActionFacts("prisoner_released_captor", hero);
				npcActionFacts2.LocationText = text;
				ApplySettlementFacts(npcActionFacts2, settlement, locationText: text);
				ApplyTargetFacts(npcActionFacts2, prisoner);
				string text4 = string.IsNullOrWhiteSpace(endCaptivityDetailLabel) ? ("你失去了对" + GetHeroDisplayName(prisoner) + "的控制。") : (GetHeroDisplayName(prisoner) + endCaptivityDetailLabel + "，不再是你的囚犯。");
				RecordNpcMajorAction(hero, text4, text2 + ":captor", npcActionFacts2);
				RecordNpcRecentAction(hero, text4, text2 + ":captor", facts: npcActionFacts2);
			}
			if (prisoner != null && prisoner != Hero.MainHero && prisoner.IsLord && (capturerFaction == Hero.MainHero?.MapFaction || party?.LeaderHero == Hero.MainHero || party?.MobileParty?.ActualClan == Clan.PlayerClan))
			{
				_recentlyReleasedPrisoners.Add(prisoner.StringId);
				string text5 = detail switch
				{
					EndCaptivityDetail.Ransom => "通过支付赎金", 
					EndCaptivityDetail.ReleasedByChoice => "被主动释放", 
					EndCaptivityDetail.ReleasedAfterPeace => "因和平协议", 
					EndCaptivityDetail.ReleasedAfterEscape => "成功逃脱", 
					_ => "", 
				};
				Logger.Log("BattleStatus", $"NPC {prisoner.Name} {text5}获得自由 (detail={detail})");
				AppendExternalDialogueHistory(prisoner, null, null, $"你{text5}从 {Hero.MainHero.Name} 的囚禁中获得了自由。");
			}
		}
		catch (Exception ex)
		{
			Logger.Log("BattleStatus", "[ERROR] OnHeroPrisonerReleased: " + ex.Message);
		}
	}

