	private static bool IsDialogueOrLetterChainBusyForMemorySummary()
	{
		try
		{
			if (Campaign.Current?.ConversationManager?.IsConversationInProgress == true)
			{
				return true;
			}
		}
		catch
		{
		}
		return false;
	}

	private static bool IsNonSceneNativeConversationActiveForMemory()
	{
		try
		{
			if (Campaign.Current?.ConversationManager?.IsConversationInProgress != true)
			{
				return false;
			}
			try
			{
				if (Mission.Current?.Scene != null && ShoutUtils.IsInValidScene())
				{
					return false;
				}
			}
			catch
			{
			}
			return true;
		}
		catch
		{
			return false;
		}
	}

	private int GetOrStartActiveNativeConversationMemorySessionId()
	{
		if (!IsNonSceneNativeConversationActiveForMemory())
		{
			_activeNativeConversationMemorySessionId = -1;
			return -1;
		}
		if (_activeNativeConversationMemorySessionId < 0)
		{
			_nativeConversationMemorySessionCounter++;
			if (_nativeConversationMemorySessionCounter <= 0)
			{
				_nativeConversationMemorySessionCounter = 1;
			}
			_activeNativeConversationMemorySessionId = _nativeConversationMemorySessionCounter;
		}
		return _activeNativeConversationMemorySessionId;
	}

	private int GetCurrentNativeConversationMemorySessionIdForSuppression()
	{
		if (!IsNonSceneNativeConversationActiveForMemory())
		{
			_activeNativeConversationMemorySessionId = -1;
			return -1;
		}
		return GetOrStartActiveNativeConversationMemorySessionId();
	}

	private string BuildCurrentMemorySessionKey(int sceneSessionId, int dialogueSessionId)
	{
		string runtimeKey = (_memoryRuntimeSessionKey ?? "").Trim();
		if (string.IsNullOrWhiteSpace(runtimeKey))
		{
			runtimeKey = Guid.NewGuid().ToString("N");
			_memoryRuntimeSessionKey = runtimeKey;
		}
		if (sceneSessionId >= 0)
		{
			return runtimeKey + ":scene:" + sceneSessionId;
		}
		if (dialogueSessionId >= 0)
		{
			return runtimeKey + ":dialogue:" + dialogueSessionId;
		}
		return runtimeKey + ":loose";
	}

	private void OnMemoryConversationEnded(IEnumerable<CharacterObject> characters)
	{
		ShoutBehavior.InvalidateNativeConversationAdmissionOnConversationEnd();
		// Authoritative end event: also retires text when a mechanism force-closes the UI.
		ConversationHelper.Clear();
		string memorySessionKey = _activeNativeConversationMemorySessionId >= 0
			? BuildCurrentMemorySessionKey(-1, _activeNativeConversationMemorySessionId)
			: string.Empty;
		PlayerNotorietyBehavior.FinalizeConversationForExternal(
			characters,
			memorySessionKey);
		_activeNativeConversationMemorySessionId = -1;
	}

	private void TryEnqueueMajorActionSummaryForDraft(DailyMemoryDraft draft, HashSet<string> queuedMajorHeroIds, bool ownerAlreadyEligible = false) => MemoryQueueState.TryEnqueueMajorActionSummaryForDraft(draft, queuedMajorHeroIds, ownerAlreadyEligible);

	private void TryEnqueueMemoryOverviewForHero(Hero hero, List<CompressedMemoryBlock> blocks = null)
	{
		try
		{
			if (!IsHeroNpcEligibleForCompressedMemory(hero))
			{
				return;
			}
			string heroId = GetMemoryHeroId(hero);
			if (string.IsNullOrWhiteSpace(heroId))
			{
				return;
			}
			TryEnqueueMemoryOverviewForMemoryId(heroId, hero.Name?.ToString() ?? "NPC", blocks ?? LoadCompressedMemoryBlocks(hero));
		}
		catch (Exception ex)
		{
			Logger.Log("MemoryOverview", "[ERROR] TryEnqueueMemoryOverviewForHero failed: " + ex.Message);
		}
	}

	private void TryEnqueueMemoryOverviewForMemoryId(string memoryId, string memoryName, List<CompressedMemoryBlock> blocks = null) => MemoryQueueState.TryEnqueueMemoryOverviewForMemoryId(memoryId, memoryName, blocks);

	private void TryEnqueueMemoryOverviewForAllCandidates()
	{
		using (PerfProbe.Scope("MyBehavior.TryEnqueueMemoryOverviewForAllCandidates"))
		{
		try
		{
			if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
			{
				return;
			}
			foreach (KeyValuePair<string, List<CompressedMemoryBlock>> item in _compressedMemoryBlocks.ToList())
			{
				string heroId = NormalizeMemoryHeroId(item.Key);
				if (string.IsNullOrWhiteSpace(heroId))
				{
					continue;
				}
				string heroName = (item.Value ?? new List<CompressedMemoryBlock>()).Select((CompressedMemoryBlock x) => x?.HeroName).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)) ?? "NPC";
				TryEnqueueMemoryOverviewForMemoryId(heroId, heroName, item.Value);
			}
			_memoryOverviewQueue = SanitizeMemoryOverviewQueue(_memoryOverviewQueue);
		}
		catch (Exception ex)
		{
			Logger.Log("MemoryOverview", "[ERROR] TryEnqueueMemoryOverviewForAllCandidates failed: " + ex.Message);
		}
		}
	}

	private void MarkMemoryOverviewDirty(string memoryId)
	{
		try
		{
			string text = NormalizeMemoryHeroId(memoryId);
			if (!IsMemoryEntityEligibleForCompressedMemory(text))
			{
				return;
			}
			_dirtyMemoryOverviewIds.Add(text);
		}
		catch
		{
		}
	}

	private void EnqueueMemoryOverviewCandidateScanId(string memoryId)
	{
		string text = NormalizeMemoryHeroId(memoryId);
		if (!IsMemoryEntityEligibleForCompressedMemory(text))
		{
			return;
		}
		if (_pendingMemoryOverviewCandidateScanIdSet.Add(text))
		{
			_pendingMemoryOverviewCandidateScanIds.Enqueue(text);
		}
	}

	private void QueueDirtyMemoryOverviewCandidatesForDeferredScan()
	{
		if (_dirtyMemoryOverviewIds.Count <= 0)
		{
			return;
		}
		foreach (string memoryId in _dirtyMemoryOverviewIds.ToList())
		{
			EnqueueMemoryOverviewCandidateScanId(memoryId);
		}
		_dirtyMemoryOverviewIds.Clear();
	}

	private void QueueAllMemoryOverviewCandidatesForDeferredScan()
	{
		if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
		{
			return;
		}
		foreach (string memoryId in _compressedMemoryBlocks.Keys.ToList())
		{
			EnqueueMemoryOverviewCandidateScanId(memoryId);
		}
	}

	private int ProcessMemoryOverviewCandidateScanBudget(long startTimestamp, double budgetMs)
	{
		int processed = 0;
		while (_pendingMemoryOverviewCandidateScanIds.Count > 0 && !IsDailyMaintenanceBudgetExceeded(startTimestamp, budgetMs))
		{
			string memoryId = _pendingMemoryOverviewCandidateScanIds.Dequeue();
			_pendingMemoryOverviewCandidateScanIdSet.Remove(memoryId);
			string text = NormalizeMemoryHeroId(memoryId);
			if (string.IsNullOrWhiteSpace(text) || _compressedMemoryBlocks == null || !_compressedMemoryBlocks.TryGetValue(text, out var blocks) || blocks == null || blocks.Count <= 0)
			{
				continue;
			}
			string heroName = blocks.Select((CompressedMemoryBlock x) => x?.HeroName).FirstOrDefault((string x) => !string.IsNullOrWhiteSpace(x)) ?? "NPC";
			TryEnqueueMemoryOverviewForMemoryId(text, heroName, blocks);
			processed++;
		}
		return processed;
	}

	private bool TrySealPastDailyMemoryDrafts(long startTimestamp = 0L, double budgetMs = double.MaxValue, bool requirePendingProbe = false)
	{
		try
		{
			if (_dailyMemoryDrafts == null || (_dailyMemoryDrafts.Count <= 0 && _dailyMemorySealState == null))
			{
				ResetDailyMemoryDraftSealSliceState();
				return true;
			}
			_memorySummaryQueue = _memorySummaryQueue ?? new List<MemorySummaryJob>();
			_npcMajorActionSummaryQueue = _npcMajorActionSummaryQueue ?? new List<MajorActionSummaryJob>();
			return ContinueDailyMemorySeal(startTimestamp, budgetMs, requirePendingProbe);
		}
		catch (Exception ex)
		{
			ResetDailyMemoryDraftSealSliceState();
			Logger.Log("CompressedMemory", "[ERROR] TrySealPastDailyMemoryDrafts failed: " + ex.Message);
			return true;
		}
	}

	private void ResetDailyMemoryDraftSealSliceState() { _memoryBusinessState.Sealing.Reset(); }

	private bool HasCompressedMemoryBlock(string heroId, int dayIndex)
	{
		heroId = NormalizeMemoryHeroId(heroId);
		if (string.IsNullOrWhiteSpace(heroId) || _compressedMemoryBlocks == null)
		{
			return false;
		}
		return _compressedMemoryBlocks.TryGetValue(heroId, out var value) && value != null && value.Any((CompressedMemoryBlock x) => x != null && x.GameDayIndex == dayIndex);
	}

	private void TryStartMemorySummaryQueue(bool forceOverviewCandidateScan = false)
	{
		try
		{
			if (_memorySummaryRunOwner.IsRunning || IsDialogueOrLetterChainBusyForMemorySummary())
			{
				return;
			}
			// Admission is O(1): eligibility can inspect every source record, so do it
			// only in the guarded planner, never again on each maintenance/entry call.
			bool hasMemoryJobs = (_memorySummaryQueue?.Count ?? 0) > 0;
			bool hasMajorActionJobs = (_npcMajorActionSummaryQueue?.Count ?? 0) > 0;
			bool hasOverviewJobs = (_memoryOverviewQueue?.Count ?? 0) > 0;
			if (!hasMemoryJobs && !hasMajorActionJobs && !hasOverviewJobs && ShouldScanMemoryOverviewCandidates(forceOverviewCandidateScan))
			{
				using (PerfProbe.Scope("MyBehavior.TryStartMemorySummaryQueue.EnqueueMemoryOverviewForAllCandidates"))
				{
					if (forceOverviewCandidateScan)
					{
						QueueAllMemoryOverviewCandidatesForDeferredScan();
					}
					else
					{
						QueueDirtyMemoryOverviewCandidatesForDeferredScan();
					}
				}
				// This only enqueues candidate IDs; the existing budgeted scanner creates jobs later.
			}
			if (!hasMemoryJobs && !hasMajorActionJobs && !hasOverviewJobs)
			{
				return;
			}
			_ = ProcessMemorySummaryQueueAsync(forceOverviewCandidateScan);
		}
		catch (Exception ex)
		{
			Logger.Log("CompressedMemory", "[ERROR] TryStartMemorySummaryQueue failed: " + ex.Message);
		}
	}

	private bool ShouldScanMemoryOverviewCandidates(bool force)
	{
		if (_compressedMemoryBlocks == null || _compressedMemoryBlocks.Count <= 0)
		{
			return false;
		}
		if (force)
		{
			_lastMemoryOverviewCandidateScanUtcTicks = DateTime.UtcNow.Ticks;
			return true;
		}
		long now = DateTime.UtcNow.Ticks;
		if (now - _lastMemoryOverviewCandidateScanUtcTicks < TimeSpan.FromSeconds(MemoryOverviewCandidateScanThrottleSeconds).Ticks)
		{
			return false;
		}
		_lastMemoryOverviewCandidateScanUtcTicks = now;
		return true;
	}

	private Task ProcessMemorySummaryQueueAsync(bool forceOverviewCandidateScan = false) => CreateMemorySummaryQueueRunRuntime().RunAsync(forceOverviewCandidateScan);

	private Task RunDailySummaryQueueItemsAsync(List<object> queueItems, int burstSize, List<MemorySummaryExecutionResult> results, List<MajorActionSummaryExecutionResult> majorResults, List<MemoryOverviewExecutionResult> overviewResults, MemorySummaryRunOwner.Lease run = null) => CreateMemorySummaryQueueRunRuntime().RunQueueItemsAsync(queueItems, burstSize, results, majorResults, overviewResults, run);

	private async Task<DailySummaryQueueResult> ExecuteDailySummaryQueueItemAsync(object item, MemorySummaryRunOwner.Lease run = null)
	{
		DailySummaryQueueResult result = new DailySummaryQueueResult();
		string expectedJobFingerprint = null;
		if (item is MemorySummaryPlanEntry planned)
		{
			expectedJobFingerprint = planned.JobFingerprint;
			item = planned.Job;
		}
		MemorySummaryJob memoryJob = item as MemorySummaryJob;
		if (memoryJob != null)
		{
			result.MemoryResult = await ExecuteMemorySummaryJobAsync(memoryJob, 3, expectedJobFingerprint, run);
			return result;
		}
		MajorActionSummaryJob majorJob = item as MajorActionSummaryJob;
		if (majorJob != null)
		{
			result.MajorActionResult = await ExecuteMajorActionSummaryJobAsync(majorJob, 3, expectedJobFingerprint, run);
			return result;
		}
		MemoryOverviewJob overviewJob = item as MemoryOverviewJob;
		if (overviewJob != null)
		{
			result.MemoryOverviewResult = await ExecuteMemoryOverviewJobAsync(overviewJob, 3, expectedJobFingerprint, run);
			return result;
		}
		return result;
	}

