		parts.Add(label.Trim() + GetSettlementSupportTendencyLabel(support.Value) + "（支持度 " + supportText + "）");
	}

	private static string GetSettlementSupportTendencyLabel(float support)
	{
		if (support >= 100f)
		{
			return "强烈支持";
		}
		if (support >= 35f)
		{
			return "支持";
		}
		if (support > 0f)
		{
			return "轻度支持";
		}
		if (support <= -100f)
		{
			return "强烈反对";
		}
		if (support <= -35f)
		{
			return "反对";
		}
		return "倾向反对";
	}

