	private static List<uint> GetBannerPaletteColors()
	{
		List<uint> list = new List<uint>();
		HashSet<uint> hashSet = new HashSet<uint>();
		for (int i = 0; i <= 1024; i++)
		{
			uint color = BannerManager.GetColor(i);
			if (color != 3735928559U && hashSet.Add(color))
			{
				list.Add(color);
			}
		}
		return list;
	}

	private static HashSet<uint> CollectUsedFactionPrimaryColors(Kingdom oldKingdom, Clan founderClan)
	{
		HashSet<uint> hashSet = new HashSet<uint>();
		try
		{
			foreach (Kingdom item in Kingdom.All)
			{
				if (item != null && !item.IsEliminated)
				{
					hashSet.Add(item.PrimaryBannerColor);
				}
			}
		}
		catch
		{
		}
		try
		{
			foreach (Clan item2 in Clan.All)
			{
				if (item2 == null || item2 == founderClan || item2.IsEliminated || item2.Kingdom != null)
				{
					continue;
				}
				if (item2.Settlements != null && item2.Settlements.Any((Settlement x) => x != null && (x.IsTown || x.IsCastle)))
				{
					hashSet.Add(item2.Banner?.GetPrimaryColor() ?? item2.Color);
				}
			}
		}
		catch
		{
		}
		if (oldKingdom != null)
		{
			hashSet.Add(oldKingdom.PrimaryBannerColor);
			hashSet.Add(oldKingdom.Color);
		}
		return hashSet;
	}

	private static int ComputeColorDistance(uint colorA, uint colorB)
	{
		return RebellionRules.ColorDistance(colorA, colorB);
	}

	private static RebelFactionColorChoice BuildRandomUniqueRebelFactionColors(Clan clan, Kingdom oldKingdom, ClanVisualSnapshot snapshot)
	{
		List<uint> bannerPaletteColors = GetBannerPaletteColors();
		uint num = snapshot?.BackgroundColor ?? RebellionRules.DefaultBackground;
		uint num2 = snapshot?.IconColor ?? uint.MaxValue;
		bool noPalette = bannerPaletteColors.Count == 0;
		var used = noPalette ? new HashSet<uint>() : CollectUsedFactionPrimaryColors(oldKingdom, clan);
		RebellionRules.SelectColors(bannerPaletteColors, used, num, num2, noPalette || BannerManager.GetColorId(num2) >= 0,
			count => MBRandom.RandomInt(count), out uint backgroundColor, out uint iconColor);
		if (noPalette)
		{
			return new RebelFactionColorChoice
			{
				BackgroundColor = backgroundColor, IconColor = iconColor,
				Banner = snapshot?.Banner != null ? new Banner(snapshot.Banner, backgroundColor, iconColor) : null
			};
		}
		Banner banner = snapshot?.Banner ?? clan?.ClanOriginalBanner ?? clan?.Banner;
		Banner banner2 = ((banner != null) ? new Banner(banner, backgroundColor, iconColor) : Banner.CreateRandomClanBanner((clan?.StringId ?? "new_kingdom").GetDeterministicHashCode()));
		banner2.ChangePrimaryColor(backgroundColor);
		if (iconColor != uint.MaxValue)
		{
			banner2.ChangeIconColors(iconColor);
		}
		return new RebelFactionColorChoice
		{
			BackgroundColor = backgroundColor,
			IconColor = iconColor,
			Banner = banner2
		};
	}

	private static void ApplyRebelFactionColorChoiceToClan(Clan clan, RebelFactionColorChoice colorChoice)
	{
		if (clan == null || colorChoice == null)
		{
			return;
		}
		clan.Color = colorChoice.BackgroundColor;
		clan.Color2 = colorChoice.IconColor;
		if (colorChoice.Banner != null)
		{
			clan.Banner = new Banner(colorChoice.Banner);
		}
		clan.UpdateBannerColor(colorChoice.BackgroundColor, colorChoice.IconColor);
	}

	private static bool IsDuplicateKingdomName(string text)
	{
		string text2 = (text ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text2))
		{
			return false;
		}
		try
		{
			return Kingdom.All.Any((Kingdom x) => x != null && string.Equals((x.Name?.ToString() ?? "").Trim(), text2, StringComparison.OrdinalIgnoreCase));
		}
		catch
		{
			return false;
		}
	}

	private static string BuildRebelKingdomNamingSystemPrompt()
	{
		return RebellionNamingRules.BuildSystemPrompt(DuelSettings.GetSettings()?.KingdomRebellionSystemPrompt);
	}

	private static string BuildRebelFollowerSummaryForNamingPrompt(IEnumerable<Clan> followerClans)
	{
		if (followerClans == null)
		{
			return "无";
		}
		List<string> list = new List<string>();
		foreach (Clan followerClan in followerClans)
		{
			if (followerClan == null)
			{
				continue;
			}
			string clanDisplayName = GetClanDisplayName(followerClan);
			string heroDisplayName = GetHeroDisplayName(followerClan.Leader);
			string text = BuildClanFortificationSummary(followerClan);
			if (string.IsNullOrWhiteSpace(text))
			{
				text = "暂无可用封地摘要";
			}
			list.Add(RebellionNamingRules.FollowerLine(clanDisplayName, heroDisplayName, text));
		}
		return RebellionNamingRules.JoinFollowerSummary(list);
	}

	private string BuildRebelKingdomNamingUserPrompt(Clan clan, Kingdom oldKingdom, int weekIndex, IEnumerable<Clan> followerClans = null, IReadOnlyCollection<string> existingNames = null)
	{
		List<string> list = new List<string>();
		if (existingNames != null) list.AddRange(existingNames);
		else
		{
		try
		{
			foreach (Kingdom item in Kingdom.All.Where((Kingdom x) => x != null))
			{
				string text = (item.Name?.ToString() ?? "").Trim();
				if (!string.IsNullOrWhiteSpace(text))
				{
					list.Add(text);
				}
			}
		}
		catch
		{
		}
		}
		string text2 = string.Join("、", list.Distinct(StringComparer.OrdinalIgnoreCase));
		List<Settlement> list2 = clan?.Settlements?.Where((Settlement x) => x != null && (x.IsTown || x.IsCastle)).ToList() ?? new List<Settlement>();
		string text3 = (list2.Count > 0) ? string.Join("、", list2.Select(GetSettlementDisplayName)) : "无";
		string rebelSettlementSummaryForNamingPrompt = BuildRebelSettlementSummaryForNamingPrompt(list2);
		string rebelFollowerSummaryForNamingPrompt = BuildRebelFollowerSummaryForNamingPrompt(followerClans);
		string heroBackgroundForRebelNamingPrompt = BuildHeroBackgroundForRebelNamingPrompt(clan?.Leader);
		string heroBackgroundForRebelNamingPrompt2 = BuildHeroBackgroundForRebelNamingPrompt(oldKingdom?.Leader);
		string kingdomBackgroundForRebelNamingPrompt = BuildKingdomBackgroundForRebelNamingPrompt(oldKingdom);
		string rebelBackgroundForNamingPrompt = BuildRebelBackgroundForNamingPrompt(oldKingdom, weekIndex);
		EventRecordEntry weeklyReportRecordByWeek = FindWeeklyReportRecordByWeek("world", "", weekIndex - 1);
		EventRecordEntry weeklyReportRecordByWeek2 = FindWeeklyReportRecordByWeek("kingdom", GetKingdomId(oldKingdom), weekIndex - 1);
		return RebellionNamingRules.BuildUserPrompt(new RebellionNamingFacts
		{
			WeekIndex = weekIndex, ClanName = GetClanDisplayName(clan), LeaderName = GetHeroDisplayName(clan?.Leader),
			CultureName = (clan?.Culture?.Name?.ToString() ?? "").Trim(), KingdomName = GetKingdomDisplayName(oldKingdom, "原王国"),
			KingName = GetHeroDisplayName(oldKingdom?.Leader), RulingClanName = GetClanDisplayName(oldKingdom?.RulingClan),
			SettlementNames = text3, RebelBackground = rebelBackgroundForNamingPrompt,
			SettlementSummary = rebelSettlementSummaryForNamingPrompt, FollowerSummary = rebelFollowerSummaryForNamingPrompt,
			LeaderBackground = heroBackgroundForRebelNamingPrompt, KingBackground = heroBackgroundForRebelNamingPrompt2,
			KingdomBackground = kingdomBackgroundForRebelNamingPrompt,
			WorldWeekly = BuildWeeklyReportLeadInForRebelNamingPrompt(weeklyReportRecordByWeek),
			KingdomWeekly = BuildWeeklyReportLeadInForRebelNamingPrompt(weeklyReportRecordByWeek2), ExistingNames = text2
		});
	}

	private void BuildRebelKingdomNamingRequest(Clan clan, Kingdom oldKingdom, int weekIndex, IEnumerable<Clan> followerClans, out string systemPrompt, out string userPrompt, IReadOnlyCollection<string> existingNames = null)
	{
		systemPrompt = BuildRebelKingdomNamingSystemPrompt();
		userPrompt = BuildRebelKingdomNamingUserPrompt(clan, oldKingdom, weekIndex, followerClans, existingNames);
	}

	private static bool TryParseRebelKingdomNamingResponse(string rawResponse, out string formalName, out string shortName, out string encyclopediaText)
	{
		return RebellionNamingRules.TryParse(rawResponse, out formalName, out shortName, out encyclopediaText);
	}

	private const int RebelKingdomNamingTimeoutMs = RebellionNamingOwner.TimeoutMs;

	private const int RebelKingdomNamingMaxAttempts = RebellionNamingOwner.MaxAttempts;

	private static RebelKingdomNamingResult BuildFailedRebelKingdomNamingResult(string failureReason, int attemptsUsed = 0)
	{
		return new RebelKingdomNamingResult
		{
			Success = false,
			FailureReason = (failureReason ?? "").Trim(),
			AttemptsUsed = Math.Max(0, attemptsUsed)
		};
	}

	private RebelKingdomNamingResult GenerateRebelKingdomNamingFromPrompts(string systemPrompt, string userPrompt, string logTarget, int maxAttempts = RebelKingdomNamingMaxAttempts, IReadOnlyCollection<string> existingNames = null)
	{
		var names = new HashSet<string>(existingNames ?? Array.Empty<string>(), StringComparer.OrdinalIgnoreCase);
		var outcome = RebellionNamingOwner.Generate(
			async () =>
			{
				var result = await CallRebelKingdomNamingGatewayDetailed(systemPrompt, userPrompt);
				return result == null ? null : new RebellionNamingAttempt
				{
					Success = result.Success, Content = result.Content, ErrorMessage = result.ErrorMessage,
					ResponseBody = result.ResponseBody, IsRateLimit = result.IsRateLimit,
					IsRequestsPerMinuteLimit = result.IsRequestsPerMinuteLimit, IsQuotaLimit = result.IsQuotaLimit,
					RetryAfterSeconds = result.RetryAfterSeconds
				};
			}, name => names.Contains(name.Trim()), LlmRetryPrompt.BuildFailureDetail,
			(attempt, total, result) => Logger.LogEventPromptExchange((logTarget ?? "叛乱建国命名") + " [尝试 " + attempt + "/" + total + "]", "【System Prompt】\n" + (systemPrompt ?? "") + "\n\n【User Prompt】\n" + (userPrompt ?? ""), result?.Success == true ? result.Content ?? "" : ("错误: " + (result?.ErrorMessage ?? "未知错误"))),
			(attempt, total, reason) => Logger.Log("KingdomRebellion", "[WARN] Rebel kingdom naming attempt failed; retrying. target=" + (logTarget ?? "") + " attempt=" + attempt + "/" + total + " reason=" + (reason ?? "")),
			GetWeeklyReportRequestIntervalMs, maxAttempts);
		return new RebelKingdomNamingResult
		{
			Success = outcome.Success, FormalName = outcome.FormalName, ShortName = outcome.ShortName,
			EncyclopediaText = outcome.EncyclopediaText, AttemptsUsed = outcome.AttemptsUsed,
			FailureReason = outcome.FailureReason, IsRateLimit = outcome.IsRateLimit,
			IsRequestsPerMinuteLimit = outcome.IsRequestsPerMinuteLimit, IsQuotaLimit = outcome.IsQuotaLimit,
			RetryAfterSeconds = outcome.RetryAfterSeconds
		};
	}

	private static string[] CaptureRebellionExistingNames()
	{
		try { return Kingdom.All.Where(x => x != null).Select(x => (x.Name?.ToString() ?? "").Trim()).Where(x => !string.IsNullOrWhiteSpace(x)).ToArray(); }
		catch { return Array.Empty<string>(); }
	}

	private RebelKingdomNamingResult GenerateRebelKingdomNaming(Clan clan, Kingdom oldKingdom, int weekIndex, IEnumerable<Clan> followerClans = null, int maxAttempts = RebelKingdomNamingMaxAttempts)
	{
		if (clan == null)
		{
			return BuildFailedRebelKingdomNamingResult("主导家族为空，无法请求命名。");
		}
		string[] rebellionExistingNames = CaptureRebellionExistingNames();
		BuildRebelKingdomNamingRequest(clan, oldKingdom, weekIndex, followerClans, out var systemPrompt, out var userPrompt, rebellionExistingNames);
		return GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, "叛乱建国命名 - " + GetClanId(clan), maxAttempts, rebellionExistingNames);
	}

	private static RebellionClanFacts CaptureRebellionClanFacts(Clan clan, Kingdom kingdom)
	{
		return new RebellionClanFacts
		{
			Exists = clan != null, KingdomExists = kingdom != null, KingdomEliminated = kingdom?.IsEliminated ?? false,
			PlayerClan = clan != null && clan == Clan.PlayerClan, InKingdom = clan != null && clan.Kingdom == kingdom,
			RulingClan = clan != null && (clan == kingdom?.RulingClan || clan == kingdom?.Leader?.Clan),
			Eliminated = clan?.IsEliminated ?? false, Bandit = clan?.IsBanditFaction ?? false,
			Minor = clan?.IsMinorFaction ?? false, Rebel = clan?.IsRebelClan ?? false,
			Mercenary = clan != null && (clan.IsUnderMercenaryService || clan.IsClanTypeMercenary),
			LeaderExists = clan?.Leader != null, LeaderAlive = clan?.Leader?.IsAlive ?? false,
			LeaderChild = clan?.Leader?.IsChild ?? false, LeaderPrisoner = clan?.Leader?.IsPrisoner ?? false
		};
	}
	private bool TryValidateClanForKingdomRebellion(Clan clan, Kingdom kingdom, bool forceTrigger, out string note, out int relationToKing, out int townCount, out int castleCount, Dictionary<Clan, RebellionClanFacts> captured = null)
	{
		RebellionClanFacts facts;
		if (clan == null || captured == null || !captured.TryGetValue(clan, out facts))
		{
			facts = CaptureRebellionClanFacts(clan, kingdom);
			if (string.IsNullOrEmpty(RebellionRules.CandidatePreflightNote(facts)))
			{
				facts.TownCount = clan.Settlements?.Count(x => x != null && x.IsTown) ?? 0;
				facts.CastleCount = clan.Settlements?.Count(x => x != null && x.IsCastle) ?? 0;
				if (string.IsNullOrEmpty(RebellionRules.CandidateNote(facts, true)))
				{
					try { facts.RelationToKing = kingdom.Leader != null ? clan.Leader.GetRelation(kingdom.Leader) : 0; }
					catch { facts.RelationToKing = 0; }
				}
			}
			if (clan != null && captured != null) captured[clan] = facts;
		}
		relationToKing = facts.RelationToKing; townCount = facts.TownCount; castleCount = facts.CastleCount;
		note = RebellionRules.CandidateNote(facts, forceTrigger);
		return string.IsNullOrEmpty(note);
	}

	private static float ComputeKingdomRebellionCandidateScore(Clan clan, Kingdom kingdom, int relationToKing, int townCount, int castleCount)
	{
		return RebellionRules.CandidateScore(new RebellionClanFacts
		{
			Renown = clan?.Renown ?? 0f, Tier = clan?.Tier ?? 0, Strength = clan?.CurrentTotalStrength ?? 0f,
			TownCount = townCount, CastleCount = castleCount, RelationToKing = relationToKing,
			SameKingCulture = clan?.Leader?.Culture != null && kingdom?.Leader?.Culture != null && clan.Leader.Culture == kingdom.Leader.Culture
		});
	}

	private bool TryValidateClanForRebelFollower(Clan clan, Kingdom kingdom, Clan leaderClan, bool forceTrigger, out string note, out int relationToKing, out int relationToLeader, out int townCount, out int castleCount, Dictionary<Clan, RebellionClanFacts> captured = null)
	{
		note = "";
		relationToKing = 0;
		relationToLeader = 0;
		townCount = 0;
		castleCount = 0;
		note = RebellionRules.FollowerPreflightNote(clan != null, leaderClan != null, clan == leaderClan);
		if (!string.IsNullOrEmpty(note)) return false;
		if (!TryValidateClanForKingdomRebellion(clan, kingdom, forceTrigger: true, out note, out relationToKing, out townCount, out castleCount, captured))
		{
			return false;
		}
		Hero leader = clan.Leader;
		Hero leader2 = leaderClan.Leader;
		note = RebellionRules.FollowerLeaderNote(leader != null, leader2 != null);
		if (!string.IsNullOrEmpty(note)) return false;
		try
		{
			relationToLeader = leader.GetRelation(leader2);
		}
		catch
		{
			relationToLeader = 0;
		}
		return true;
	}

	private static bool IsEligibleRebelFollowerByStandardRules(int relationToKing, int relationToLeader, float score)
	{
		return RebellionRules.FollowerEligible(relationToKing, relationToLeader);
	}

	private static bool IsEligibleRebelFollowerByRelativeFallback(int relationToKing, int relationToLeader, float score)
	{
		return RebellionRules.FollowerFallback();
	}

	private static float ComputeKingdomRebellionFollowerScore(Clan clan, Kingdom kingdom, Clan leaderClan, int relationToKing, int relationToLeader)
	{
		return RebellionRules.FollowerScore(new RebellionClanFacts
		{
			RelationToKing = relationToKing, RelationToLeader = relationToLeader,
			SameLeaderCulture = clan?.Leader?.Culture != null && leaderClan?.Leader?.Culture != null && clan.Leader.Culture == leaderClan.Leader.Culture,
			SameKingCulture = clan?.Leader?.Culture != null && kingdom?.Leader?.Culture != null && clan.Leader.Culture == kingdom.Leader.Culture
		});
	}

	private List<KingdomRebellionFollowerInfo> EvaluateKingdomRebellionFollowers(Kingdom kingdom, Clan leaderClan, bool forceTrigger, Dictionary<Clan, RebellionClanFacts> captured = null)
	{
		captured ??= new Dictionary<Clan, RebellionClanFacts>();
		List<KingdomRebellionFollowerInfo> list = new List<KingdomRebellionFollowerInfo>();
		if (kingdom == null || leaderClan == null)
		{
			return list;
		}
		IEnumerable<Clan> enumerable = kingdom.Clans ?? Enumerable.Empty<Clan>();
		foreach (Clan clan in enumerable)
		{
			if (clan == null)
			{
				continue;
			}
			KingdomRebellionFollowerInfo kingdomRebellionFollowerInfo = new KingdomRebellionFollowerInfo
			{
				Clan = clan,
				ClanId = GetClanId(clan),
				ClanName = GetClanDisplayName(clan)
			};
			if (!TryValidateClanForRebelFollower(clan, kingdom, leaderClan, forceTrigger, out var note, out var relationToKing, out var relationToLeader, out var townCount, out var castleCount, captured))
			{
				kingdomRebellionFollowerInfo.Eligible = false;
				kingdomRebellionFollowerInfo.Note = note;
				kingdomRebellionFollowerInfo.RelationToKing = relationToKing;
				kingdomRebellionFollowerInfo.RelationToLeader = relationToLeader;
				kingdomRebellionFollowerInfo.TownCount = Math.Max(0, townCount);
				kingdomRebellionFollowerInfo.CastleCount = Math.Max(0, castleCount);
				kingdomRebellionFollowerInfo.ClanTier = Math.Max(0, clan.Tier);
			}
			else
			{
				kingdomRebellionFollowerInfo.RelationToKing = relationToKing;
				kingdomRebellionFollowerInfo.RelationToLeader = relationToLeader;
				kingdomRebellionFollowerInfo.TownCount = townCount;
				kingdomRebellionFollowerInfo.CastleCount = castleCount;
				kingdomRebellionFollowerInfo.ClanTier = Math.Max(0, clan.Tier);
				kingdomRebellionFollowerInfo.Score = ComputeKingdomRebellionFollowerScore(clan, kingdom, leaderClan, relationToKing, relationToLeader);
				bool flag = IsEligibleRebelFollowerByStandardRules(relationToKing, relationToLeader, kingdomRebellionFollowerInfo.Score);
				bool flag2 = IsEligibleRebelFollowerByRelativeFallback(relationToKing, relationToLeader, kingdomRebellionFollowerInfo.Score);
				kingdomRebellionFollowerInfo.Eligible = flag || flag2;
				int num = relationToLeader - relationToKing;
				if (flag)
				{
					kingdomRebellionFollowerInfo.Note = "满足联合叛乱跟随条件：对叛乱领袖关系减去对国王关系 = " + num + "（>= 15）。";
				}
				else
				{
					kingdomRebellionFollowerInfo.Note = "不满足联合叛乱跟随条件：对叛乱领袖关系减去对国王关系 = " + num + "（需 >= 15）。";
				}
			}
			list.Add(kingdomRebellionFollowerInfo);
		}
		return RebellionRules.Sort(list, x => x.Eligible, x => x.Score, x => x.ClanName);
	}

	private List<KingdomRebellionCandidateInfo> EvaluateKingdomRebellionCandidates(Kingdom kingdom, bool forceTrigger, Dictionary<Clan, RebellionClanFacts> captured = null)
	{
		captured ??= new Dictionary<Clan, RebellionClanFacts>();
		List<KingdomRebellionCandidateInfo> list = new List<KingdomRebellionCandidateInfo>();
		if (kingdom == null)
		{
			return list;
		}
		IEnumerable<Clan> enumerable = kingdom.Clans ?? Enumerable.Empty<Clan>();
		foreach (Clan clan in enumerable)
		{
			if (clan == null)
			{
				continue;
			}
			KingdomRebellionCandidateInfo kingdomRebellionCandidateInfo = new KingdomRebellionCandidateInfo
			{
				Clan = clan,
				ClanId = GetClanId(clan),
				ClanName = GetClanDisplayName(clan)
			};
			if (!TryValidateClanForKingdomRebellion(clan, kingdom, forceTrigger, out var note, out var relationToKing, out var townCount, out var castleCount, captured))
			{
				kingdomRebellionCandidateInfo.Eligible = false;
				kingdomRebellionCandidateInfo.Note = note;
				kingdomRebellionCandidateInfo.RelationToKing = relationToKing;
				kingdomRebellionCandidateInfo.TownCount = Math.Max(0, townCount);
				kingdomRebellionCandidateInfo.CastleCount = Math.Max(0, castleCount);
				kingdomRebellionCandidateInfo.TotalFortificationCount = kingdomRebellionCandidateInfo.TownCount + kingdomRebellionCandidateInfo.CastleCount;
				kingdomRebellionCandidateInfo.ClanTier = Math.Max(0, clan.Tier);
			}
			else
			{
				kingdomRebellionCandidateInfo.Eligible = true;
				kingdomRebellionCandidateInfo.Note = forceTrigger ? "满足强制触发条件。" : "满足自动叛乱条件。";
				kingdomRebellionCandidateInfo.RelationToKing = relationToKing;
				kingdomRebellionCandidateInfo.TownCount = townCount;
				kingdomRebellionCandidateInfo.CastleCount = castleCount;
				kingdomRebellionCandidateInfo.TotalFortificationCount = townCount + castleCount;
				kingdomRebellionCandidateInfo.ClanTier = Math.Max(0, clan.Tier);
				kingdomRebellionCandidateInfo.Score = ComputeKingdomRebellionCandidateScore(clan, kingdom, relationToKing, townCount, castleCount);
			}
			list.Add(kingdomRebellionCandidateInfo);
		}
		return RebellionRules.Sort(list, x => x.Eligible, x => x.Score, x => x.ClanName);
	}

	private KingdomRebellionResolutionResult ResolveKingdomRebellion(Kingdom kingdom, int weekIndex, bool executeAction, bool forceTrigger)
	{
		KingdomRebellionResolutionResult kingdomRebellionResolutionResult = new KingdomRebellionResolutionResult
		{
			Kingdom = kingdom,
			WeekIndex = weekIndex,
			Forced = forceTrigger
		};
		if (kingdom == null)
		{
			kingdomRebellionResolutionResult.Message = "找不到目标王国。";
			return kingdomRebellionResolutionResult;
		}
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			kingdomRebellionResolutionResult.Message = "王国稳定度与叛乱功能已在 MCM 中关闭，跳过叛乱判定。";
			return kingdomRebellionResolutionResult;
		}
		int kingdomStabilityValue = GetKingdomStabilityValue(kingdom);
		kingdomRebellionResolutionResult.StabilityValue = kingdomStabilityValue;
		kingdomRebellionResolutionResult.StabilityTierText = GetKingdomStabilityTierText(kingdomStabilityValue);
		kingdomRebellionResolutionResult.TriggerChance = GetKingdomRebellionWeeklyChance(kingdomStabilityValue);
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			kingdomRebellionResolutionResult.TriggerChance = 0f;
			kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，跳过本模组稳定度叛乱判定。";
			return kingdomRebellionResolutionResult;
		}
		if (kingdom.IsEliminated)
		{
			kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "已灭亡，跳过叛乱判定。";
			return kingdomRebellionResolutionResult;
		}
		if (kingdom.Leader == null)
		{
			kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "当前缺少有效领袖，跳过叛乱判定。";
			return kingdomRebellionResolutionResult;
		}
		var captured = new Dictionary<Clan, RebellionClanFacts>();
		kingdomRebellionResolutionResult.Candidates = EvaluateKingdomRebellionCandidates(kingdom, forceTrigger: false, captured: captured);
		foreach (KingdomRebellionCandidateInfo item in kingdomRebellionResolutionResult.Candidates.Where((KingdomRebellionCandidateInfo x) => x != null && x.Clan != null))
		{
			item.PreviewFollowerClanNames = EvaluateKingdomRebellionFollowers(kingdom, item.Clan, forceTrigger: false, captured: captured).Where((KingdomRebellionFollowerInfo x) => x != null && x.Eligible && x.Clan != null).Select((KingdomRebellionFollowerInfo x) => GetClanDisplayName(x.Clan)).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
		}
		if (!forceTrigger)
		{
			if (kingdomRebellionResolutionResult.TriggerChance <= 0f)
			{
				kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "当前稳定度为“" + kingdomRebellionResolutionResult.StabilityTierText + "”，本周没有叛乱概率。";
				return kingdomRebellionResolutionResult;
			}
			bool passed = RebellionRules.PassChance(false, kingdomRebellionResolutionResult.TriggerChance, () => MBRandom.RandomFloat, out float randomFloat);
			kingdomRebellionResolutionResult.Roll = randomFloat;
			kingdomRebellionResolutionResult.PassedChanceGate = passed;
			if (!kingdomRebellionResolutionResult.PassedChanceGate)
			{
				kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "本周叛乱抽签未命中。当前档位“" + kingdomRebellionResolutionResult.StabilityTierText + "”，概率 " + FormatKingdomRebellionChance(kingdomRebellionResolutionResult.TriggerChance) + "，本次掷值 " + randomFloat.ToString("0.000") + "。";
				return kingdomRebellionResolutionResult;
			}
		}
		else
		{
			kingdomRebellionResolutionResult.PassedChanceGate = true;
		}
		KingdomRebellionCandidateInfo kingdomRebellionCandidateInfo = RebellionRules.FirstEligible(kingdomRebellionResolutionResult.Candidates, x => x != null && x.Eligible && x.Clan != null);
		if (kingdomRebellionCandidateInfo == null)
		{
			kingdomRebellionResolutionResult.Message = GetKingdomDisplayName(kingdom, "该王国") + "当前没有满足条件的带城叛乱候选家族。";
			return kingdomRebellionResolutionResult;
		}
		kingdomRebellionResolutionResult.SelectedClan = kingdomRebellionCandidateInfo.Clan;
		kingdomRebellionResolutionResult.FollowerCandidates = EvaluateKingdomRebellionFollowers(kingdom, kingdomRebellionCandidateInfo.Clan, forceTrigger: false, captured: captured);
		kingdomRebellionResolutionResult.SelectedFollowerClans = kingdomRebellionResolutionResult.FollowerCandidates.Where((KingdomRebellionFollowerInfo x) => x != null && x.Eligible && x.Clan != null).Select((KingdomRebellionFollowerInfo x) => x.Clan).ToList();
		if (!executeAction)
		{
			string text = (kingdomRebellionResolutionResult.SelectedFollowerClans.Count > 0) ? ("；预计跟随家族 " + string.Join("、", kingdomRebellionResolutionResult.SelectedFollowerClans.Select(GetClanDisplayName))) : "；当前没有会联合响应的其他家族。";
			kingdomRebellionResolutionResult.Message = "当前最可能反出的家族是 " + kingdomRebellionCandidateInfo.ClanName + "（关系 " + kingdomRebellionCandidateInfo.RelationToKing + "，评分 " + kingdomRebellionCandidateInfo.Score.ToString("0.0") + "）" + text;
			return kingdomRebellionResolutionResult;
		}
		kingdomRebellionResolutionResult.Executed = TryExecuteKingdomRebellion(kingdomRebellionCandidateInfo.Clan, kingdom, weekIndex, forceTrigger, kingdomRebellionResolutionResult.SelectedFollowerClans, out var message);
		kingdomRebellionResolutionResult.Message = message;
		return kingdomRebellionResolutionResult;
	}

	private bool TryExecuteKingdomRebellion(Clan clan, Kingdom kingdom, int weekIndex, bool forceTrigger, List<Clan> followerClans, out string message)
	{
		message = "";
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			message = "执行叛乱失败：该王国当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫。";
			return false;
		}
		if (!TryValidateClanForKingdomRebellion(clan, kingdom, forceTrigger: true, out var note, out var relationToKing, out var townCount, out var castleCount))
		{
			message = "执行叛乱失败：" + note;
			return false;
		}
		try
		{
			RebelKingdomNamingResult rebelKingdomNamingResult = GenerateRebelKingdomNaming(clan, kingdom, weekIndex, followerClans);
			return TryExecuteKingdomRebellionWithNaming(clan, kingdom, weekIndex, forceTrigger, relationToKing, townCount, castleCount, rebelKingdomNamingResult, followerClans, out message);
		}
		catch (Exception ex)
		{
			message = "执行叛乱失败：" + ex.Message;
			Logger.Log("KingdomRebellion", "[ERROR] TryExecuteKingdomRebellion failed: " + ex);
			return false;
		}
	}

	private static bool IsRebelKingdomNamingSuccess(RebelKingdomNamingResult namingResult)
	{
		return namingResult != null && namingResult.Success && !string.IsNullOrWhiteSpace(namingResult.FormalName) && !string.IsNullOrWhiteSpace(namingResult.ShortName) && !string.IsNullOrWhiteSpace(namingResult.EncyclopediaText);
	}

	private static string BuildRebelKingdomNamingFailureExecutionMessage(RebelKingdomNamingResult namingResult)
	{
		int attempts = Math.Max(0, namingResult?.AttemptsUsed ?? 0);
		string text = attempts > 0 ? ("叛乱建国命名已连续自动重试 " + attempts + "/" + RebelKingdomNamingMaxAttempts + " 次仍失败，已中止本次建国。") : "叛乱建国命名未能完成，已中止本次建国。";
		string failureReason = (namingResult?.FailureReason ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(failureReason))
		{
			// 原始 API 响应可能很长；交互窗口只保留恢复动作，详情由左下角通知和日志承载。
			text += " 最后一次失败详情已显示在左下角消息并写入日志。";
		}
		return text + " 请重新填写事件/叛乱API信息后再试。";
	}

	private static void AppendRebelKingdomNamingResultLines(StringBuilder stringBuilder, RebelKingdomNamingResult namingResult)
	{
		if (stringBuilder == null)
		{
			return;
		}
		stringBuilder.AppendLine("命名结果：");
		if (IsRebelKingdomNamingSuccess(namingResult))
		{
			stringBuilder.AppendLine("- 正式名：" + ((namingResult.FormalName ?? "").Trim()));
			stringBuilder.AppendLine("- 简称：" + ((namingResult.ShortName ?? "").Trim()));
			stringBuilder.AppendLine("- 来源：LLM");
			if (!string.IsNullOrWhiteSpace(namingResult.EncyclopediaText))
			{
				stringBuilder.AppendLine("- 百科简介：" + namingResult.EncyclopediaText.Trim());
			}
			return;
		}
		stringBuilder.AppendLine("- 状态：失败");
		stringBuilder.AppendLine("- 自动重试次数：" + Math.Max(namingResult?.AttemptsUsed ?? 0, 0) + "/" + RebelKingdomNamingMaxAttempts);
		if (namingResult?.IsRequestsPerMinuteLimit == true)
		{
			stringBuilder.AppendLine("- 限流判断：疑似 RPM 超限");
		}
		else if (namingResult?.IsQuotaLimit == true)
		{
			stringBuilder.AppendLine("- 限流判断：疑似额度/余额不足");
		}
		else if (namingResult?.IsRateLimit == true)
		{
			stringBuilder.AppendLine("- 限流判断：接口限流");
		}
		if (namingResult?.RetryAfterSeconds != null)
		{
			stringBuilder.AppendLine("- 接口建议等待：" + namingResult.RetryAfterSeconds.Value + " 秒");
		}
		if (!string.IsNullOrWhiteSpace(namingResult?.FailureReason))
		{
			// 避免完整模型/API 响应把重试或修复按钮推出可视区域。
			stringBuilder.AppendLine("- 最后一次失败详情已显示在左下角消息并写入日志。");
		}
	}

	private static void ReportRebelKingdomNamingFailure(RebelKingdomNamingResult namingResult)
	{
		string failureReason = (namingResult?.FailureReason ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(failureReason))
		{
			// 仅在失败 UI 已经准备显示时报告一次，避免后台重试过程反复打断玩家。
			NonBlockingErrorReport.Show("叛乱建国命名失败", failureReason);
		}
	}

	private bool TryExecuteKingdomRebellionWithNaming(Clan clan, Kingdom kingdom, int weekIndex, bool forceTrigger, int relationToKing, int townCount, int castleCount, RebelKingdomNamingResult rebelKingdomNamingResult, List<Clan> followerClans, out string message)
	{
		message = "";
		string kingdomDisplayName = GetKingdomDisplayName(kingdom, "该王国");
		string clanDisplayName = GetClanDisplayName(clan);
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			message = kingdomDisplayName + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次稳定度叛乱已跳过。";
			Logger.Log("KingdomRebellion", "[SKIP] player kingdom stability rebellion immunity blocked execution. kingdom=" + GetKingdomId(kingdom) + " clan=" + GetClanId(clan) + " forced=" + forceTrigger);
			return false;
		}
		if (!IsRebelKingdomNamingSuccess(rebelKingdomNamingResult))
		{
			message = BuildRebelKingdomNamingFailureExecutionMessage(rebelKingdomNamingResult);
			Logger.Log("KingdomRebellion", "[ERROR] Rebel kingdom creation blocked because naming failed. clan=" + GetClanId(clan) + " attempts=" + (rebelKingdomNamingResult?.AttemptsUsed ?? 0) + " reason=" + (rebelKingdomNamingResult?.FailureReason ?? ""));
			return false;
		}
		string text = NormalizeRebelKingdomNameToken(rebelKingdomNamingResult?.FormalName ?? "", 24);
		string text2 = NormalizeRebelKingdomNameToken(rebelKingdomNamingResult?.ShortName ?? "", 14);
		string text3 = NormalizeRebelKingdomLoreText(rebelKingdomNamingResult?.EncyclopediaText ?? "");
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(text2) || string.IsNullOrWhiteSpace(text3) || IsDuplicateKingdomName(text))
		{
			message = "叛乱建国命名结果无效或与现有王国重名，已中止建国。请重新填写事件/叛乱API信息后再试。";
			Logger.Log("KingdomRebellion", "[ERROR] Rebel kingdom creation blocked by invalid naming result. clan=" + GetClanId(clan) + " formal=" + text + " short=" + text2);
			return false;
		}
		if (Campaign.Current?.KingdomManager == null || clan == null || clan.Kingdom != kingdom || clan.IsEliminated || clan.Leader == null || !clan.Leader.IsAlive)
		{
			message = "建国前条件已变化，未离开原王国。";
			return false;
		}
		ClanVisualSnapshot clanVisualSnapshot = CaptureClanVisualSnapshot(clan);
		ChangeKingdomAction.ApplyByLeaveWithRebellionAgainstKingdom(clan, showNotification: true);
		RestoreClanVisualSnapshot(clan, clanVisualSnapshot);
		RebelFactionColorChoice rebelFactionColorChoice = BuildRandomUniqueRebelFactionColors(clan, kingdom, clanVisualSnapshot);
		ApplyRebelFactionColorChoiceToClan(clan, rebelFactionColorChoice);
		KingdomManager kingdomManager = Campaign.Current?.KingdomManager;
		if (kingdomManager == null)
		{
			message = clanDisplayName + " 已从 " + kingdomDisplayName + " 反出，但当前未找到 KingdomManager，未能继续建立新王国。";
			Logger.Log("KingdomRebellion", "[ERROR] KingdomManager unavailable after rebellion leave. clan=" + GetClanId(clan));
			return true;
		}
		kingdomManager.CreateKingdom(new TextObject(text, null), new TextObject(text2, null), clan.Culture ?? kingdom.Culture, clan, null, new TextObject(text3, null), new TextObject(text, null), null);
		Kingdom kingdom2 = clan.Kingdom;
		if (kingdom2 == null || kingdom2 == kingdom || kingdom2.IsEliminated)
		{
			message = "家族已离开原王国，但建国结果尚未确认。";
			return false;
		}
		if (kingdom != null && !kingdom.IsEliminated)
		{
			SetKingdomStabilityValue(kingdom, KingdomStabilityDefaultValue);
		}
		if (kingdom2 != null && !kingdom2.IsEliminated)
		{
			MarkModCreatedRebelKingdom(kingdom2);
			SetKingdomStabilityValue(kingdom2, RebelKingdomInitialStabilityValue); PacifyInheritedRebelWars(kingdom2, kingdom);
		}
		List<string> list = new List<string>();
		if (kingdom2 != null && followerClans != null && followerClans.Count > 0)
		{
			foreach (Clan followerClan in followerClans.Where((Clan x) => x != null && x != clan).GroupBy((Clan x) => GetClanId(x), StringComparer.OrdinalIgnoreCase).Select((IGrouping<string, Clan> x) => x.First()))
			{
				try
				{
					if (followerClan.IsEliminated || followerClan.Kingdom != kingdom || followerClan.IsUnderMercenaryService || followerClan.IsClanTypeMercenary)
					{
						continue;
					}
					ChangeKingdomAction.ApplyByJoinToKingdomByDefection(followerClan, kingdom, kingdom2, default(CampaignTime), showNotification: true);
					list.Add(GetClanDisplayName(followerClan));
					MarkClanVisualsDirty(followerClan);
				}
				catch (Exception ex)
				{
					Logger.Log("KingdomRebellion", "[WARN] Failed to attach follower clan to rebel kingdom. leader=" + GetClanId(clan) + " follower=" + GetClanId(followerClan) + " error=" + ex.Message);
				}
			}
		}
		MarkClanVisualsDirty(clan);
		string clanFortificationSummary = BuildClanFortificationSummary(clan);
		message = clanDisplayName + " 已从 " + kingdomDisplayName + " 反出，并建立了 " + text + "。";
		if (!string.IsNullOrWhiteSpace(clanFortificationSummary))
		{
			message = message + " " + clanFortificationSummary;
		}
		if (list.Count > 0)
		{
			message = message + " 联合响应家族：" + string.Join("、", list) + "。";
		}
		TryDiscontinueLandlessKingdom(kingdom, "rebellion_old_kingdom:" + GetClanId(clan), requireKnownModRebelKingdom: false, allowPlayerKingdom: true);
		Logger.Log("KingdomRebellion", "[EXECUTE] week=" + weekIndex + " kingdom=" + GetKingdomId(kingdom) + " clan=" + GetClanId(clan) + " forced=" + forceTrigger + " relation=" + relationToKing + " towns=" + townCount + " castles=" + castleCount + " newKingdomName=" + text + " namingAttempts=" + (rebelKingdomNamingResult?.AttemptsUsed ?? 0) + " followerCount=" + list.Count + " followers=" + string.Join("|", list) + " bgColor=0x" + rebelFactionColorChoice.BackgroundColor.ToString("X8") + " iconColor=0x" + rebelFactionColorChoice.IconColor.ToString("X8"));
		return true;
	}

	private void MarkModCreatedRebelKingdom(Kingdom kingdom)
	{
		_rebelKingdomIdentity.Mark(GetKingdomId(kingdom));
	}

	private bool IsKnownOrLegacyModCreatedRebelKingdom(Kingdom kingdom)
	{
		string id = GetKingdomId(kingdom);
		return RebellionRules.IsKnownOrLegacy(id, _rebelKingdomIdentity.IsKnown(id), _kingdomStabilityValues != null && _kingdomStabilityValues.ContainsKey(id));
	}

	private static Clan FindKingdomClanMatchingBanner(Kingdom kingdom, Banner banner, Clan excludedClan)
	{
		try
		{
			if (kingdom?.Clans == null || banner == null)
			{
				return null;
			}
			return kingdom.Clans.FirstOrDefault((Clan clan) => clan != null && clan != excludedClan && clan.Banner != null && clan.Banner.IsContentsSameWith(banner));
		}
		catch
		{
			return null;
		}
	}

	private static HashSet<string> BuildEventSourceMaterialStableKeySet(List<EventSourceMaterialEntry> source)
	{
		return new HashSet<string>(SanitizeEventSourceMaterials(source).Select((EventSourceMaterialEntry x) => (x?.StableKey ?? "").Trim()).Where((string x) => !string.IsNullOrWhiteSpace(x)), StringComparer.OrdinalIgnoreCase);
	}

	private HashSet<string> BuildEventSourceMaterialStableKeySet()
	{
		return BuildEventSourceMaterialStableKeySet(_eventSourceMaterials);
	}

	private static void MarkKingdomBannerVisualsDirty(Kingdom kingdom)
	{
		try
		{
			foreach (Clan clan in (kingdom?.Clans?.ToList() ?? new List<Clan>()))
			{
				MarkClanVisualsDirty(clan);
			}
		}
		catch
		{
		}
	}

	private bool TrySyncModCreatedRebelKingdomBannerToRulingClan(Kingdom kingdom, Clan eventRulingClan, string reason)
	{
		try
		{
			if (kingdom == null || kingdom.IsEliminated || !IsKnownOrLegacyModCreatedRebelKingdom(kingdom))
			{
				return false;
			}
			Clan rulingClan = kingdom.RulingClan;
			if (rulingClan == null || rulingClan.IsEliminated || rulingClan.Kingdom != kingdom || rulingClan.Banner == null)
			{
				Logger.Log("KingdomRebellion", "[ruler_banner_sync_skipped] reason=" + (reason ?? "") + " kingdom=" + GetKingdomId(kingdom) + " rulingClan=" + GetClanId(rulingClan) + " result=invalid_ruling_clan_or_banner");
				return false;
			}
			Banner banner = kingdom.Banner;
			if (banner != null && banner.IsContentsSameWith(rulingClan.Banner))
			{
				return false;
			}
			Clan clan = FindKingdomClanMatchingBanner(kingdom, banner, rulingClan);
			kingdom.Banner = new Banner(rulingClan.Banner);
			MarkKingdomBannerVisualsDirty(kingdom);
			Logger.Log("KingdomRebellion", "[ruler_banner_synced] reason=" + (reason ?? "") + " kingdom=" + GetKingdomId(kingdom) + " previousBannerClan=" + GetClanId(clan) + " eventClan=" + GetClanId(eventRulingClan) + " rulingClan=" + GetClanId(rulingClan) + " result=updated");
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("KingdomRebellion", "[ERROR] ruler_banner_sync_failed reason=" + (reason ?? "") + " kingdom=" + GetKingdomId(kingdom) + " eventClan=" + GetClanId(eventRulingClan) + " error=" + ex.Message);
			return false;
		}
	}

	private void SyncModCreatedRebelKingdomBannersOnGameLoad()
	{
		try
		{
			foreach (Kingdom kingdom in (Kingdom.All?.ToList() ?? new List<Kingdom>()))
			{
				TrySyncModCreatedRebelKingdomBannerToRulingClan(kingdom, null, "game_load_finished");
			}
		}
		catch (Exception ex)
		{
			Logger.Log("KingdomRebellion", "[ERROR] ruler_banner_load_sync_failed error=" + ex.Message);
		}
	}

	private bool TryDiscontinueLandlessKingdom(Kingdom kingdom, string reason, bool requireKnownModRebelKingdom, bool allowPlayerKingdom)
	{
		try
		{
			if (!RebellionRules.CanDiscontinue(kingdom != null, kingdom?.IsEliminated ?? false,
				Clan.PlayerClan?.Kingdom == kingdom, kingdom?.Settlements != null && kingdom.Settlements.Count > 0,
				!requireKnownModRebelKingdom || IsKnownOrLegacyModCreatedRebelKingdom(kingdom), allowPlayerKingdom)) return false;
			bool canBeDiscontinued = true;
			CampaignEventDispatcher.Instance.CanKingdomBeDiscontinued(kingdom, ref canBeDiscontinued);
			if (!canBeDiscontinued)
			{
				Logger.Log("KingdomRebellion", "[landless_kingdom_discontinue_vetoed] reason=" + (reason ?? "") + " kingdom=" + GetKingdomId(kingdom));
				return false;
			}
			string kingdomId = GetKingdomId(kingdom);
			if (requireKnownModRebelKingdom) PacifyInheritedRebelWars(kingdom, null); int clanCount = kingdom.Clans?.Count ?? 0;
			int settlementCount = kingdom.Settlements?.Count ?? 0;
			foreach (Clan clan in (kingdom.Clans?.ToList() ?? new List<Clan>()))
			{
				if (clan == null)
				{
					continue;
				}
				FinalizeMapEventsForKingdomDiscontinuation(clan);
				if (!clan.IsEliminated && clan.Kingdom == kingdom)
				{
					ChangeKingdomAction.ApplyByLeaveByKingdomDestruction(clan, showNotification: true);
				}
			}
			kingdom.RulingClan = null;
			if (!kingdom.IsEliminated)
			{
				DestroyKingdomAction.Apply(kingdom);
			}
			if (requireKnownModRebelKingdom)
			{
				CleanupModCreatedRebelKingdomState(kingdomId);
			}
			Logger.Log("KingdomRebellion", "[landless_kingdom_discontinued] reason=" + (reason ?? "") + " kingdom=" + kingdomId + " clans=" + clanCount + " settlements=" + settlementCount + " requireKnownModRebelKingdom=" + requireKnownModRebelKingdom);
			return true;
		}
		catch (Exception ex)
		{
			Logger.Log("KingdomRebellion", "[ERROR] landless_kingdom_discontinue failed kingdom=" + GetKingdomId(kingdom) + " reason=" + (reason ?? "") + " error=" + ex.Message);
			return false;
		}
	}

	private bool TryDiscontinueLandlessModRebelKingdom(Kingdom kingdom, string reason)
	{
		return TryDiscontinueLandlessKingdom(kingdom, reason, requireKnownModRebelKingdom: true, allowPlayerKingdom: false);
	}

	private void TryDiscontinueLandlessModRebelKingdoms(string reason)
	{
		try
		{
			bool scannedKnownRebelKingdom = false;
			foreach (string kingdomId in _rebelKingdomIdentity.Snapshot().ToList())
			{
				string text = (kingdomId ?? "").Trim();
				if (string.IsNullOrWhiteSpace(text))
				{
					continue;
				}
				Kingdom kingdom = FindKingdomById(text);
				if (kingdom == null)
				{
					CleanupModCreatedRebelKingdomState(text);
					continue;
				}
				scannedKnownRebelKingdom = true;
				TryDiscontinueLandlessModRebelKingdom(kingdom, reason);
			}
			if (scannedKnownRebelKingdom)
			{
				return;
			}
			if (Kingdom.All == null || Kingdom.All.Count == 0)
			{
				return;
			}
			foreach (Kingdom kingdom in Kingdom.All.Where((Kingdom x) => x != null).ToList())
			{
				TryDiscontinueLandlessModRebelKingdom(kingdom, reason);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("KingdomRebellion", "[ERROR] landless_mod_rebel_kingdom_scan failed reason=" + (reason ?? "") + " error=" + ex.Message);
		}
	}

	private static void FinalizeMapEventsForKingdomDiscontinuation(Clan clan)
	{
		if (clan == null)
		{
			return;
		}
		foreach (WarPartyComponent warPartyComponent in (clan.WarPartyComponents?.ToList() ?? new List<WarPartyComponent>()))
		{
			MobileParty mobileParty = warPartyComponent?.MobileParty;
			if (mobileParty == null || warPartyComponent?.Party == null || !warPartyComponent.Party.IsActive)
			{
				continue;
			}
			if (mobileParty.MapEvent != null)
			{
				mobileParty.MapEvent.FinalizeEvent();
			}
			if (mobileParty.SiegeEvent != null)
			{
				mobileParty.SiegeEvent.FinalizeSiegeEvent();
			}
		}
		foreach (Settlement settlement in (clan.Settlements?.ToList() ?? new List<Settlement>()))
		{
			if (settlement?.Party?.MapEvent != null)
			{
				settlement.Party.MapEvent.FinalizeEvent();
			}
			if (settlement?.Party?.SiegeEvent != null)
			{
				settlement.Party.SiegeEvent.FinalizeSiegeEvent();
			}
		}
	}

	private void CleanupModCreatedRebelKingdomState(string kingdomId)
	{
		string text = (kingdomId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		_rebelKingdomIdentity.Remove(text);
		_modCreatedRebelKingdomIdStorage?.Remove(text);
		_kingdomStabilityValues?.Remove(text);
		_kingdomStabilityStorage?.Remove(text);
		if (_kingdomStabilityRelationAppliedOffsets != null)
		{
			foreach (string key in _kingdomStabilityRelationAppliedOffsets.Keys.Where((string x) => !string.IsNullOrWhiteSpace(x) && x.StartsWith(text + "|", StringComparison.OrdinalIgnoreCase)).ToList())
			{
				_kingdomStabilityRelationAppliedOffsets.Remove(key);
			}
		}
		if (_kingdomStabilityRelationOffsetStorage != null)
		{
			foreach (string key2 in _kingdomStabilityRelationOffsetStorage.Keys.Where((string x) => !string.IsNullOrWhiteSpace(x) && x.StartsWith(text + "|", StringComparison.OrdinalIgnoreCase)).ToList())
			{
				_kingdomStabilityRelationOffsetStorage.Remove(key2);
			}
		}
	}

	private void TryProcessWeeklyKingdomRebellions(int weekIndex)
	{
		while (!ProcessWeeklyKingdomRebellionsSlice(weekIndex))
		{
		}
	}

	private bool ProcessWeeklyKingdomRebellionsSlice(int weekIndex)
	{
		if (weekIndex <= 0 || _lastProcessedKingdomRebellionWeek >= weekIndex)
		{
			ResetPendingWeeklyKingdomRebellionMaintenance();
			return true;
		}
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			CancelPendingAutomaticKingdomRebellions("disabled_by_mcm");
			ResetPendingWeeklyKingdomRebellionMaintenance();
			_lastProcessedKingdomRebellionWeek = Math.Max(_lastProcessedKingdomRebellionWeek, weekIndex);
			Logger.Log("KingdomRebellion", "[SKIP] 王国稳定度与叛乱功能已在 MCM 中关闭，跳过 week=" + weekIndex + " 的自动叛乱判定。");
			return true;
		}
		try
		{
			KingdomMaintenance.BeginWeek(weekIndex, GetDevEditableKingdoms);
			if (KingdomMaintenance.TryTake(out Kingdom devEditableKingdom))
			{
				try
				{
					using (PerfProbe.Scope("MyBehavior.WeeklyKingdomRebellions.ResolveKingdom"))
					{
						int kingdomStabilityValue = GetKingdomStabilityValue(devEditableKingdom);
						int kingdomStabilityWeeklyBalancingDelta = GetKingdomStabilityWeeklyBalancingDelta(kingdomStabilityValue);
						if (kingdomStabilityWeeklyBalancingDelta != 0)
						{
							SetKingdomStabilityValue(devEditableKingdom, kingdomStabilityValue + kingdomStabilityWeeklyBalancingDelta);
						}
TeamModuleServices.CivilWar.AdvanceWeek(devEditableKingdom, weekIndex, GetKingdomStabilityValue(devEditableKingdom), (target, delta) =>
								{
									int before = GetKingdomStabilityValue(target);
									SetKingdomStabilityValue(target, before + delta);
								}, GetRecentKingdomEventFactsForExternal(GetKingdomId(devEditableKingdom), 8));
								if (TeamModuleServices.CivilWar.HasTrackedKingdom(devEditableKingdom) || TeamModuleServices.CivilWar.BlocksNewOffensiveWar(devEditableKingdom))
							{
								return KingdomMaintenance.Complete && CompleteWeeklyKingdomRebellionMaintenance(weekIndex);
							}
							KingdomRebellionResolutionResult kingdomRebellionResolutionResult = ResolveKingdomRebellion(devEditableKingdom, weekIndex, executeAction: false, forceTrigger: false);
						if (kingdomRebellionResolutionResult != null && kingdomRebellionResolutionResult.PassedChanceGate && kingdomRebellionResolutionResult.SelectedClan != null)
						{
							QueueAutomaticKingdomRebellion(kingdomRebellionResolutionResult);
						}
					}
				}
				catch (Exception ex)
				{
					Logger.Log("KingdomRebellion", "[ERROR] Weekly resolution failed for kingdom " + GetKingdomId(devEditableKingdom) + ": " + ex.Message);
				}
				return KingdomMaintenance.Complete && CompleteWeeklyKingdomRebellionMaintenance(weekIndex);
			}
			return CompleteWeeklyKingdomRebellionMaintenance(weekIndex);
		}
		catch (Exception ex2)
		{
			Logger.Log("KingdomRebellion", "[ERROR] ProcessWeeklyKingdomRebellionsSlice failed: " + ex2);
			ResetPendingWeeklyKingdomRebellionMaintenance();
			return true;
		}
	}

	private bool CompleteWeeklyKingdomRebellionMaintenance(int weekIndex)
	{
		_lastProcessedKingdomRebellionWeek = Math.Max(_lastProcessedKingdomRebellionWeek, weekIndex);
		ResetPendingWeeklyKingdomRebellionMaintenance();
		if (AutomaticKingdomRebellions.ActivateIfQueued())
		{
			TryStartNextAutomaticKingdomRebellionAsync();
		}
		return true;
	}

	private void ResetPendingWeeklyKingdomRebellionMaintenance()
	{
		KingdomMaintenance.ResetWeek();
	}

	public static void QueueCivilWarSplitForExternal(Kingdom kingdom, Clan clan)
		{
			try
			{
				MyBehavior behavior = Instance ?? Campaign.Current?.GetCampaignBehavior<MyBehavior>();
				if (behavior == null || kingdom == null || clan == null) return;
				int week = Math.Max(1, GetCurrentGameDayIndexSafe() / 7);
				var result = new KingdomRebellionResolutionResult
				{
					Kingdom = kingdom,
					WeekIndex = week,
					Forced = true,
					SelectedClan = clan,
					PassedChanceGate = true,
					StabilityValue = behavior.GetKingdomStabilityValue(kingdom)
				};
				behavior.QueueAutomaticKingdomRebellion(result);
				behavior.TryStartNextAutomaticKingdomRebellionAsync();
			}
			catch (Exception ex)
			{
				Logger.Log("KingdomCivilWar", "[ERROR] split queue failed: " + ex.Message);
			}
		}

		public static void QueueCivilWarRebellionForExternal(Kingdom kingdom, Clan leader, List<Clan> followers, string factionId, bool startNow)
		{
			try
			{
				MyBehavior behavior = Instance ?? Campaign.Current?.GetCampaignBehavior<MyBehavior>();
				if (behavior == null || kingdom == null || leader == null || string.IsNullOrWhiteSpace(factionId)) return;
				KingdomRebellionResolutionResult result = new KingdomRebellionResolutionResult
				{
					Kingdom = kingdom,
					WeekIndex = Math.Max(1, GetCurrentGameDayIndexSafe() / 7),
					Forced = true,
					SelectedClan = leader,
					SelectedFollowerClans = followers ?? new List<Clan>(),
					PassedChanceGate = true,
					StabilityValue = behavior.GetKingdomStabilityValue(kingdom)
				};
				behavior.QueueAutomaticKingdomRebellion(result, factionId);
				if (startNow) behavior.TryStartNextAutomaticKingdomRebellionAsync();
			}
			catch (Exception ex)
			{
				Logger.Log("KingdomCivilWar", "[ERROR] civil war rebellion queue failed: " + ex.Message);
			}
		}

		private void QueueAutomaticKingdomRebellion(KingdomRebellionResolutionResult result, string civilWarFactionId = null)
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			return;
		}
		if (result?.Kingdom == null || result.SelectedClan == null)
		{
			return;
		}
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(result.Kingdom))
		{
			Logger.Log("KingdomRebellion", "[SKIP] player kingdom stability rebellion immunity blocked automatic queue. kingdom=" + GetKingdomId(result.Kingdom) + " clan=" + GetClanId(result.SelectedClan));
			return;
		}
		KingdomRebellionCandidateInfo kingdomRebellionCandidateInfo = result.Candidates?.FirstOrDefault((KingdomRebellionCandidateInfo x) => x != null && x.Clan == result.SelectedClan);
		PendingAutomaticKingdomRebellionContext item = new PendingAutomaticKingdomRebellionContext
		{
			KingdomId = GetKingdomId(result.Kingdom),
			ClanId = GetClanId(result.SelectedClan),
			WeekIndex = result.WeekIndex,
			StabilityValue = result.StabilityValue,
			StabilityTierText = result.StabilityTierText,
			RelationToKing = kingdomRebellionCandidateInfo?.RelationToKing ?? 0,
			TownCount = kingdomRebellionCandidateInfo?.TownCount ?? 0,
			CastleCount = kingdomRebellionCandidateInfo?.CastleCount ?? 0,
			FollowerClanIds = (result.SelectedFollowerClans ?? new List<Clan>()).Where((Clan x) => x != null && x != result.SelectedClan).Select(GetClanId).Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList()
			,
			CivilWarFactionId = civilWarFactionId ?? ""
		};
		AutomaticKingdomRebellions.Enqueue(item);
	}

	private void CancelPendingAutomaticKingdomRebellions(string reason)
	{
		AutomaticKingdomRebellions.Cancel();
		Logger.Log("KingdomRebellion", "[CANCEL] Pending automatic rebellions cleared. reason=" + (reason ?? ""));
	}

	private void TryStartNextAutomaticKingdomRebellionAsync()
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			CancelPendingAutomaticKingdomRebellions("disabled_before_start");
			TryStartDeferredAutoWeeklyReports();
			return;
		}
		if (!AutomaticKingdomRebellions.TryDequeue(out PendingAutomaticKingdomRebellionContext pendingAutomaticKingdomRebellionContext))
		{
			return;
		}
		Kingdom kingdom = FindKingdomById(pendingAutomaticKingdomRebellionContext.KingdomId);
		Clan clan = FindClanById(pendingAutomaticKingdomRebellionContext.ClanId);
		List<Clan> list = (pendingAutomaticKingdomRebellionContext.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
		if (IsStaleCivilWarRebellion(pendingAutomaticKingdomRebellionContext))
		{
			ContinueAutomaticKingdomRebellionFlow();
			return;
		}
		if (kingdom == null || clan == null)
		{
			NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, "目标王国或家族状态已变化");
			ShowAutomaticKingdomRebellionCompletionPopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, success: false, "本周自动叛乱已命中，但目标王国或家族状态已变化，无法继续执行。");
			return;
		}
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			Logger.Log("KingdomRebellion", "[SKIP] player kingdom stability rebellion immunity blocked queued automatic rebellion before naming. kingdom=" + GetKingdomId(kingdom) + " clan=" + GetClanId(clan));
			NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, "玩家王国稳定度叛乱免疫");
			ContinueAutomaticKingdomRebellionFlow();
			return;
		}
		string[] rebellionExistingNames = CaptureRebellionExistingNames();
		BuildRebelKingdomNamingRequest(clan, kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex, list, out var systemPrompt, out var userPrompt, rebellionExistingNames);
		long namingRequestVersion = AutomaticKingdomRebellions.BeginNaming();
		InformationManager.ShowInquiry(new InquiryData("正在生成叛乱建国命名", "系统正在为本周自动叛乱生成新王国的名称与百科简介。\n\n这一步完成前不会继续本轮自动叛乱与周报流程。\n请稍候，结果完成后会自动弹出。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		string logTarget = "自动叛乱建国命名 - " + GetClanId(clan);
		Task.Run(delegate
		{
			RebelKingdomNamingResult namingResult;
			try
			{
				namingResult = GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, logTarget, RebelKingdomNamingMaxAttempts, rebellionExistingNames);
			}
			catch (Exception ex)
			{
				namingResult = BuildFailedRebelKingdomNamingResult("叛乱建国命名后台任务异常：" + ex.Message);
			}
			EnqueueKingdomRebellionNamingMainThreadAction(runtimeGeneration, delegate
			{
				if (AutomaticKingdomRebellions.CompleteNaming(namingRequestVersion, pendingAutomaticKingdomRebellionContext))
					pendingAutomaticKingdomRebellionContext.NamingResult = namingResult;
			}, "automatic_rebellion_naming");
		});
	}

	private void ProcessPendingAutomaticKingdomRebellionResult()
	{
		if (!AutomaticKingdomRebellions.TryTakeReady(out PendingAutomaticKingdomRebellionContext pendingAutomaticKingdomRebellionContext))
		{
			return;
		}
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			CancelPendingAutomaticKingdomRebellions("disabled_before_execute");
			TryStartDeferredAutoWeeklyReports();
			return;
		}
		if (pendingAutomaticKingdomRebellionContext == null)
		{
			return;
		}
		Kingdom kingdom = FindKingdomById(pendingAutomaticKingdomRebellionContext.KingdomId);
		Clan clan = FindClanById(pendingAutomaticKingdomRebellionContext.ClanId);
		List<Clan> list = (pendingAutomaticKingdomRebellionContext.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
		string executionMessage;
		bool success;
		// The civil-war faction may have timed out or dissolved while the name was being generated.
		if (IsStaleCivilWarRebellion(pendingAutomaticKingdomRebellionContext))
		{
			InformationManager.HideInquiry();
			ContinueAutomaticKingdomRebellionFlow();
			return;
		}
		if (kingdom == null || clan == null)
		{
			success = false;
			executionMessage = "叛乱命名已完成，但目标王国或家族状态已变化，无法继续执行。";
		}
		else if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			success = false;
			executionMessage = GetKingdomDisplayName(kingdom, "该王国") + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次自动稳定度叛乱已跳过。";
		}
		else
		{
			if (!IsRebelKingdomNamingSuccess(pendingAutomaticKingdomRebellionContext.NamingResult))
			{
				ShowAutomaticKingdomRebellionNamingFailurePopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, afterApiRepair: false);
				return;
			}
			success = TryExecuteKingdomRebellionWithNaming(clan, kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex, forceTrigger: false, pendingAutomaticKingdomRebellionContext.RelationToKing, pendingAutomaticKingdomRebellionContext.TownCount, pendingAutomaticKingdomRebellionContext.CastleCount, pendingAutomaticKingdomRebellionContext.NamingResult, list, out executionMessage);
			if (success && !string.IsNullOrWhiteSpace(pendingAutomaticKingdomRebellionContext.CivilWarFactionId))
			{
				TeamModuleServices.CivilWar.NotifyRebelKingdomCreated(pendingAutomaticKingdomRebellionContext.CivilWarFactionId, clan?.Kingdom, pendingAutomaticKingdomRebellionContext.WeekIndex);
			}
		}
		if (!success) NotifyCivilWarRebellionFailed(pendingAutomaticKingdomRebellionContext, executionMessage);
		ShowAutomaticKingdomRebellionCompletionPopup(pendingAutomaticKingdomRebellionContext, kingdom, clan, list, success, executionMessage);
	}

	// Civil-war requests: the owner may have dissolved the faction while this entry waited in the queue.
	private static bool IsStaleCivilWarRebellion(PendingAutomaticKingdomRebellionContext context)
	{
		string factionId = context?.CivilWarFactionId;
		if (string.IsNullOrWhiteSpace(factionId) || TeamModuleServices.CivilWar.IsRebellionRequestActive(factionId)) return false;
		Logger.Log("KingdomCivilWar", "[SKIP] stale civil war rebellion request faction=" + factionId);
		return true;
	}

	private static void NotifyCivilWarRebellionFailed(PendingAutomaticKingdomRebellionContext context, string reason)
	{
		if (!string.IsNullOrWhiteSpace(context?.CivilWarFactionId)) TeamModuleServices.CivilWar.NotifyRebellionFailed(context.CivilWarFactionId, reason);
	}

	private void ShowAutomaticKingdomRebellionCompletionPopup(PendingAutomaticKingdomRebellionContext context, Kingdom kingdom, Clan clan, List<Clan> followerClans, bool success, string executionMessage)
	{
		StringBuilder stringBuilder = new StringBuilder();
		if (kingdom != null)
		{
			stringBuilder.AppendLine("王国：" + GetKingdomDisplayName(kingdom, "某王国"));
		}
		if (!string.IsNullOrWhiteSpace(context?.StabilityTierText))
		{
			stringBuilder.AppendLine("触发时稳定度：" + context.StabilityValue + "（" + context.StabilityTierText + "）");
		}
		if (clan != null)
		{
			stringBuilder.AppendLine("主导家族：" + GetClanDisplayName(clan));
		}
		if (context?.NamingResult != null)
		{
			if (!success)
			{
				ReportRebelKingdomNamingFailure(context.NamingResult);
			}
			stringBuilder.AppendLine();
			AppendRebelKingdomNamingResultLines(stringBuilder, context.NamingResult);
		}
		if (followerClans != null && followerClans.Count > 0)
		{
			stringBuilder.AppendLine();
			stringBuilder.AppendLine("联合响应家族：");
			stringBuilder.AppendLine("- " + string.Join("、", followerClans.Select(GetClanDisplayName)));
		}
		stringBuilder.AppendLine();
		stringBuilder.AppendLine("执行结果：");
		stringBuilder.AppendLine((executionMessage ?? "").Trim());
		if (AutomaticKingdomRebellions.PendingCount > 0)
		{
			stringBuilder.AppendLine();
			stringBuilder.AppendLine("后续仍有 " + AutomaticKingdomRebellions.PendingCount + " 场自动叛乱待处理。点击“继续”后将进入下一场。");
		}
		InformationManager.HideInquiry();
		InformationManager.ShowInquiry(new InquiryData(success ? "自动叛乱执行完成" : "自动叛乱执行失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: false, "继续", "", delegate
		{
			ContinueAutomaticKingdomRebellionFlow();
		}, null), pauseGameActiveState: true);
	}

	private void ShowAutomaticKingdomRebellionNamingFailurePopup(PendingAutomaticKingdomRebellionContext context, Kingdom kingdom, Clan clan, List<Clan> followerClans, bool afterApiRepair)
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine("本周自动叛乱已命中，但叛乱建国命名没有成功。系统不会使用本地国名继续建国。");
		stringBuilder.AppendLine();
		if (kingdom != null)
		{
			stringBuilder.AppendLine("王国：" + GetKingdomDisplayName(kingdom, "某王国"));
		}
		if (clan != null)
		{
			stringBuilder.AppendLine("主导家族：" + GetClanDisplayName(clan));
		}
		if (followerClans != null && followerClans.Count > 0)
		{
			stringBuilder.AppendLine("联合响应家族：" + string.Join("、", followerClans.Select(GetClanDisplayName)));
		}
		stringBuilder.AppendLine();
		ReportRebelKingdomNamingFailure(context?.NamingResult);
		AppendRebelKingdomNamingResultLines(stringBuilder, context?.NamingResult);
		stringBuilder.AppendLine();
		stringBuilder.AppendLine(afterApiRepair ? "API 配置流程已返回。请重新生成叛乱建国命名，或跳过本次自动叛乱。" : "请先重新填写事件/叛乱API信息。修正后可回到这里重新生成命名。");
		InformationManager.HideInquiry();
		InformationManager.ShowInquiry(new InquiryData(afterApiRepair ? "重试叛乱建国命名" : "叛乱建国命名失败", stringBuilder.ToString().TrimEnd(), isAffirmativeOptionShown: true, isNegativeOptionShown: true, afterApiRepair ? "重新生成命名" : "调整API信息", "跳过本次", delegate
		{
			if (afterApiRepair)
			{
				RetryAutomaticKingdomRebellionNamingAsync(context);
			}
			else
			{
				_blockedAutomaticKingdomRebellionContext = context;
				_blockedDevForcedKingdomRebellionContext = null;
				OpenKingdomRebellionApiRepairFlow();
			}
		}, delegate
		{
			if (ReferenceEquals(_blockedAutomaticKingdomRebellionContext, context))
			{
				_blockedAutomaticKingdomRebellionContext = null;
			}
			_kingdomRebellionReopenAfterApiConfig = false;
			NotifyCivilWarRebellionFailed(context, "跳过了叛乱建国命名");
			ContinueAutomaticKingdomRebellionFlow();
		}), pauseGameActiveState: true);
	}

	private void RetryAutomaticKingdomRebellionNamingAsync(PendingAutomaticKingdomRebellionContext context)
	{
		_blockedAutomaticKingdomRebellionContext = null;
		_kingdomRebellionReopenAfterApiConfig = false;
		if (context == null)
		{
			ContinueAutomaticKingdomRebellionFlow();
			return;
		}
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			CancelPendingAutomaticKingdomRebellions("disabled_before_rebellion_naming_retry");
			TryStartDeferredAutoWeeklyReports();
			return;
		}
		if (!AutomaticKingdomRebellions.CanStart)
		{
			return;
		}
		Kingdom kingdom = FindKingdomById(context.KingdomId);
		Clan clan = FindClanById(context.ClanId);
		List<Clan> list = (context.FollowerClanIds ?? new List<string>()).Select(FindClanById).Where((Clan x) => x != null && x != clan).ToList();
		// The player may have spent weeks in the API repair flow; the civil-war faction may be gone by now.
		if (IsStaleCivilWarRebellion(context))
		{
			ContinueAutomaticKingdomRebellionFlow();
			return;
		}
		if (kingdom == null || clan == null)
		{
			NotifyCivilWarRebellionFailed(context, "目标王国或家族状态已变化");
			ShowAutomaticKingdomRebellionCompletionPopup(context, kingdom, clan, list, success: false, "叛乱命名重试前目标王国或家族状态已变化，无法继续执行。");
			return;
		}
		if (PlayerKingdomRebellionImmunity.ShouldProtectKingdom(kingdom))
		{
			NotifyCivilWarRebellionFailed(context, "玩家王国稳定度叛乱免疫");
			ShowAutomaticKingdomRebellionCompletionPopup(context, kingdom, clan, list, success: false, GetKingdomDisplayName(kingdom, "该王国") + " 当前由玩家作为国王统治，且 MCM 已开启玩家王国稳定度叛乱免疫，本次自动稳定度叛乱已跳过。");
			return;
		}
		string[] rebellionExistingNames = CaptureRebellionExistingNames();
		BuildRebelKingdomNamingRequest(clan, kingdom, context.WeekIndex, list, out var systemPrompt, out var userPrompt, rebellionExistingNames);
		long namingRequestVersion = AutomaticKingdomRebellions.BeginNaming();
		InformationManager.ShowInquiry(new InquiryData("正在重新生成叛乱建国命名", "系统正在按修正后的事件/叛乱API配置重新请求新王国名称与百科简介。\n\n这一步完成前不会继续本轮自动叛乱与周报流程。", isAffirmativeOptionShown: false, isNegativeOptionShown: false, "", "", null, null), pauseGameActiveState: true);
		long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
		string logTarget = "自动叛乱建国命名重试 - " + GetClanId(clan);
		Task.Run(delegate
		{
			RebelKingdomNamingResult namingResult;
			try
			{
				namingResult = GenerateRebelKingdomNamingFromPrompts(systemPrompt, userPrompt, logTarget, RebelKingdomNamingMaxAttempts, rebellionExistingNames);
			}
			catch (Exception ex)
			{
				namingResult = BuildFailedRebelKingdomNamingResult("叛乱建国命名重试后台任务异常：" + ex.Message);
			}
			EnqueueKingdomRebellionNamingMainThreadAction(runtimeGeneration, delegate
			{
				if (AutomaticKingdomRebellions.CompleteNaming(namingRequestVersion, context))
					context.NamingResult = namingResult;
			}, "automatic_rebellion_naming_retry");
		});
	}

	private void ContinueAutomaticKingdomRebellionFlow()
	{
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			CancelPendingAutomaticKingdomRebellions("disabled_before_continue");
			TryStartDeferredAutoWeeklyReports();
			return;
		}
		if (AutomaticKingdomRebellions.PendingCount > 0)
		{
			TryStartNextAutomaticKingdomRebellionAsync();
			return;
		}
		AutomaticKingdomRebellions.FinishFlow();
		TryStartDeferredAutoWeeklyReports();
	}

	private static Settlement ResolveGatheringPointSettlement(IMapPoint gatheringPoint, MobileParty fallbackParty = null)
	{
		if (gatheringPoint is Settlement settlement)
		{
			return settlement;
		}
		try
		{
			if (gatheringPoint != null)
			{
				Settlement settlement2 = Helpers.SettlementHelper.FindNearestSettlementToPoint(gatheringPoint.Position, (Settlement x) => x != null && !x.IsHideout);
				if (settlement2 != null)
				{
					return settlement2;
				}
			}
		}
		catch
		{
		}
		try
		{
			if (fallbackParty != null)
			{
				return Helpers.SettlementHelper.FindNearestSettlementToMobileParty(fallbackParty, MobileParty.NavigationType.All, (Settlement x) => x != null && !x.IsHideout);
			}
		}
		catch
		{
		}
		return null;
	}

	private static Settlement ResolveSettlementForPartyBase(PartyBase party)
	{
		MobileParty mobileParty = party?.MobileParty;
		if (mobileParty == null)
		{
			return null;
		}
		return mobileParty.BesiegedSettlement ?? ResolveSiegeSettlement(mobileParty.SiegeEvent) ?? mobileParty.TargetSettlement ?? mobileParty.CurrentSettlement ?? mobileParty.LastVisitedSettlement;
	}

	private static string GetLocationLabelForPartyBase(PartyBase party)
	{
		string text = GetNearestSettlementNameForParty(party?.MobileParty);
		return string.IsNullOrWhiteSpace(text) ? "" : text;
	}

	private static string ResolveGatheringPointLabel(IMapPoint gatheringPoint, MobileParty fallbackParty = null)
	{
		Settlement settlement = ResolveGatheringPointSettlement(gatheringPoint, fallbackParty);
		string text = (settlement?.Name?.ToString() ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		text = (gatheringPoint?.Name?.ToString() ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text) && !string.Equals(text, "集结地", StringComparison.OrdinalIgnoreCase) && !string.Equals(text, "Gathering Point", StringComparison.OrdinalIgnoreCase))
		{
			return text;
		}
		text = GetNearestSettlementNameForParty(fallbackParty);
		return string.IsNullOrWhiteSpace(text) ? "集结地" : text;
	}

	private static NpcActionFacts CreateNpcActionFacts(string actionKind, Hero actorHero = null)
	{
		NpcActionFacts npcActionFacts = new NpcActionFacts
		{
			ActionKind = (actionKind ?? "").Trim()
		};
		ApplyActorFacts(npcActionFacts, actorHero);
		return npcActionFacts;
	}

	private static void ApplyActorFacts(NpcActionFacts facts, Hero hero)
	{
		if (facts == null || hero == null)
		{
			return;
		}
		facts.ActorHeroId = GetHeroId(hero);
		facts.ActorClanId = GetClanId(hero.Clan);
		facts.ActorKingdomId = GetKingdomId(hero.MapFaction);
		AddUniqueId(facts.RelatedHeroIds, facts.ActorHeroId);
		AddUniqueId(facts.RelatedClanIds, facts.ActorClanId);
		AddUniqueId(facts.RelatedKingdomIds, facts.ActorKingdomId);
	}

	private static void ApplyTargetFacts(NpcActionFacts facts, Hero hero)
	{
		if (facts == null || hero == null)
		{
			return;
		}
		facts.TargetHeroId = GetHeroId(hero);
		facts.TargetClanId = GetClanId(hero.Clan);
		facts.TargetKingdomId = GetKingdomId(hero.MapFaction);
		AddUniqueId(facts.RelatedHeroIds, facts.TargetHeroId);
		AddUniqueId(facts.RelatedClanIds, facts.TargetClanId);
		AddUniqueId(facts.RelatedKingdomIds, facts.TargetKingdomId);
	}

	private static void ApplySettlementFacts(NpcActionFacts facts, Settlement settlement, Hero currentOwnerOverride = null, Hero previousOwnerOverride = null, string locationText = null)
	{
		if (facts == null || settlement == null)
		{
			return;
		}
		facts.SettlementId = GetSettlementId(settlement);
		facts.SettlementName = (settlement.Name?.ToString() ?? "").Trim();
		facts.LocationText = string.IsNullOrWhiteSpace(locationText) ? facts.SettlementName : locationText.Trim();
		Hero hero = currentOwnerOverride ?? settlement.OwnerClan?.Leader;
		Hero hero2 = previousOwnerOverride;
		facts.SettlementOwnerHeroId = GetHeroId(hero);
		facts.SettlementOwnerClanId = GetClanId(hero?.Clan ?? settlement.OwnerClan);
		facts.SettlementOwnerKingdomId = GetKingdomId(hero?.MapFaction ?? settlement.MapFaction);
		facts.PreviousSettlementOwnerHeroId = GetHeroId(hero2);
		facts.PreviousSettlementOwnerClanId = GetClanId(hero2?.Clan);
		facts.PreviousSettlementOwnerKingdomId = GetKingdomId(hero2?.MapFaction);
		AddUniqueId(facts.RelatedHeroIds, facts.SettlementOwnerHeroId);
		AddUniqueId(facts.RelatedClanIds, facts.SettlementOwnerClanId);
		AddUniqueId(facts.RelatedKingdomIds, facts.SettlementOwnerKingdomId);
		AddUniqueId(facts.RelatedHeroIds, facts.PreviousSettlementOwnerHeroId);
		AddUniqueId(facts.RelatedClanIds, facts.PreviousSettlementOwnerClanId);
		AddUniqueId(facts.RelatedKingdomIds, facts.PreviousSettlementOwnerKingdomId);
	}

	private static void AddRelatedFactionFacts(NpcActionFacts facts, IFaction faction)
	{
		if (facts == null || faction == null)
		{
			return;
		}
		if (faction is Kingdom kingdom)
		{
			string kingdomId = GetKingdomId(kingdom);
			if (string.IsNullOrWhiteSpace(facts.TargetKingdomId))
			{
				facts.TargetKingdomId = kingdomId;
			}
			AddUniqueId(facts.RelatedKingdomIds, kingdomId);
			return;
		}
		if (faction is Clan clan)
		{
			string clanId = GetClanId(clan);
			if (string.IsNullOrWhiteSpace(facts.TargetClanId))
			{
				facts.TargetClanId = clanId;
			}
			if (string.IsNullOrWhiteSpace(facts.TargetKingdomId))
			{
				facts.TargetKingdomId = GetKingdomId(clan.Kingdom);
			}
			AddUniqueId(facts.RelatedClanIds, clanId);
			AddUniqueId(facts.RelatedKingdomIds, GetKingdomId(clan.Kingdom));
		}
	}

	private static void AddUniqueId(List<string> list, string id)
	{
		string text = (id ?? "").Trim();
		if (list == null || string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		if (!list.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
		{
			list.Add(text);
		}
	}

	private static void CopyFactIds(List<string> source, List<string> destination)
	{
		if (source == null || destination == null)
		{
			return;
		}
		foreach (string item in source)
		{
			AddUniqueId(destination, item);
		}
	}

	public static List<string> GetRecentKingdomEventFactsForExternal(string kingdomId, int limit)
		{
			List<string> facts = new List<string>();
			try
			{
				MyBehavior behavior = Instance ?? Campaign.Current?.GetCampaignBehavior<MyBehavior>();
				string id = (kingdomId ?? "").Trim();
				if (behavior?._eventSourceMaterials == null || string.IsNullOrWhiteSpace(id)) return facts;
				foreach (EventSourceMaterialEntry entry in behavior._eventSourceMaterials.Where(x => x != null && string.Equals((x.KingdomId ?? "").Trim(), id, StringComparison.OrdinalIgnoreCase)).Reverse().Take(Math.Max(1, limit)))
				{
					string kind = (entry.MaterialKind ?? "").Trim();
					if (kind != "war_declared" && kind != "peace_made" && kind != "raid_completed" && kind != "kingdom_decision_support" && kind != "clan_destroyed" && kind != "player_execution" && kind != "siege_aftermath") continue;
					facts.Add(kind + "\t" + (entry.StableKey ?? "") + "\t" + LimitEventFact((entry.Label ?? "") + " " + (entry.SnapshotText ?? "")));
				}
			}
			catch (Exception ex)
			{
				Logger.Log("KingdomCivilWar", "[WARN] recent event facts failed: " + ex.Message);
			}
			return facts;
		}

		private static string LimitEventFact(string text)
		{
			string value = (text ?? "").Replace("\r", " ").Replace("\n", " ").Trim();
			return value.Length <= 80 ? value : value.Substring(0, 80);
		}

