	private static string BuildNpcInventorySummaryHeader(Hero npcHero)
	{
		string text = (npcHero?.Name?.ToString() ?? "").Replace("\r", "").Replace("\n", "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "NPC";
		}
		string title = npcHero != null && npcHero != Hero.MainHero && npcHero.IsLord
			? text + "携带的所有物资和财富"
			: text + "的商铺可用财富与物品";
		return "【" + title + "】(注意：你不可以转移超出数量的物品，钱，如果你没有那么多，请实话实说)";
	}

