	private List<string> BuildNonHeroPartyMemoryNeedles(MobileParty mobileParty, PartyBase partyBase = null)
	{
		List<string> needles = new List<string>();
		try
		{
			PartyBase resolvedPartyBase = partyBase ?? mobileParty?.Party;
			string stringId = NormalizeMemoryHeroId(mobileParty?.StringId);
			if (!string.IsNullOrWhiteSpace(stringId))
			{
				// MobileParty.StringId 是随存档保存的唯一对象 ID，是非 hero 野外部队记忆的主键。
				needles.Add("|party:party_string_id:" + stringId);
				// 兼容旧版曾经写入的未标注 StringId 记录；只用 StringId，不用显示名称。
				needles.Add("|party:" + stringId);
			}
			if (mobileParty != null && _wildernessNonHeroPartyMemoryIds != null && _wildernessNonHeroPartyMemoryIds.TryGetValue(mobileParty, out var guid))
			{
				string normalizedGuid = NormalizeMemoryHeroId(guid);
				if (!string.IsNullOrWhiteSpace(normalizedGuid))
				{
					// 仅作为没有 StringId 的异常部队兜底；销毁时仍要能清掉旧 GUID 记忆。
					needles.Add("|party:party_guid:" + normalizedGuid);
				}
			}
			if (resolvedPartyBase != null && resolvedPartyBase.Index >= 0)
			{
				// party_index 只清理当前会话里已存在的旧 fallback 记录，不能作为读档后的持久主键。
				needles.Add("|party:party_index:" + resolvedPartyBase.Index);
			}
		}
		catch
		{
		}
		return needles.Where((string x) => !string.IsNullOrWhiteSpace(x)).Distinct(StringComparer.OrdinalIgnoreCase).ToList();
	}

	private static bool ContainsExactNonHeroPartyNeedle(string memoryId, string partyNeedle)
	{
		string text = NormalizeMemoryHeroId(memoryId);
		string needle = NormalizeMemoryHeroId(partyNeedle);
		if (string.IsNullOrWhiteSpace(text) || string.IsNullOrWhiteSpace(needle))
		{
			return false;
		}
		int index = text.IndexOf(needle, StringComparison.OrdinalIgnoreCase);
		while (index >= 0)
		{
			int after = index + needle.Length;
			if (after >= text.Length || text[after] == '|')
			{
				return true;
			}
			index = text.IndexOf(needle, index + 1, StringComparison.OrdinalIgnoreCase);
		}
		return false;
	}

	private static bool IsNonHeroMemoryIdForParty(string memoryId, List<string> partyNeedles)
	{
		string text = NormalizeMemoryHeroId(memoryId);
		if (string.IsNullOrWhiteSpace(text) || !IsNonHeroMemoryId(text) || partyNeedles == null || partyNeedles.Count == 0)
		{
			return false;
		}
		return partyNeedles.Any((string needle) => ContainsExactNonHeroPartyNeedle(text, needle));
	}

	private bool CancelUnavailableHeroCompressionWorkById(string memoryId, string reason) => MemoryQueueState.CancelUnavailableHeroCompressionWorkById(memoryId, reason);

	private void CancelUnavailableHeroCompressionWorkAfterLoad()
	{
		try
		{
			// This is a single load-time registry pass, not a per-tick Hero.FindFirst scan over saved memory.
			HashSet<string> eligibleHeroIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			int observedAliveHeroCount = 0;
			foreach (Hero hero in Hero.AllAliveHeroes)
			{
				observedAliveHeroCount++;
				if (IsHeroNpcEligibleForCompressedMemory(hero))
				{
					eligibleHeroIds.Add(GetMemoryHeroId(hero));
				}
			}
			if (observedAliveHeroCount <= 0)
			{
				Logger.Log("CompressedMemory", "skip unavailable hero compression cancellation because the alive Hero registry is empty at load finish");
				return;
			}
			HashSet<string> candidateIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			void AddCandidateIds(IEnumerable<string> ids)
			{
				foreach (string id in ids ?? Enumerable.Empty<string>())
				{
					string normalizedId = NormalizeMemoryHeroId(id);
					if (!string.IsNullOrWhiteSpace(normalizedId) && !IsNonHeroMemoryId(normalizedId))
					{
						candidateIds.Add(normalizedId);
					}
				}
			}
			AddCandidateIds(_dailyMemoryDrafts?.Keys);
			AddCandidateIds(_compressedMemoryBlocks?.Keys);
			AddCandidateIds(_memoryOverviewStates?.Keys);
			AddCandidateIds(_memoryOverviewStateStorage?.Keys);
			AddCandidateIds(_npcMajorActionSummaries?.Keys);
			AddCandidateIds(_npcMajorActionSummaryStorage?.Keys);
			AddCandidateIds((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Select((MemorySummaryJob x) => x?.HeroId));
			AddCandidateIds((_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Select((MemoryOverviewJob x) => x?.HeroId));
			AddCandidateIds((_npcMajorActionSummaryQueue ?? new List<MajorActionSummaryJob>()).Select((MajorActionSummaryJob x) => x?.HeroId));
			AddCandidateIds(_dirtyMemoryOverviewIds);
			AddCandidateIds(_pendingMemoryOverviewCandidateScanIds);
			int cancelledCount = 0;
			foreach (string id in candidateIds)
			{
				if (!eligibleHeroIds.Contains(id) && CancelUnavailableHeroCompressionWorkById(id, "game_load_finished"))
				{
					cancelledCount++;
				}
			}
			if (cancelledCount > 0)
			{
				Logger.Log("CompressedMemory", "cancelled unavailable hero compression work after load count=" + cancelledCount);
			}
		}
		catch (Exception ex)
		{
			Logger.Log("CompressedMemory", "[WARN] unavailable hero compression cancellation after load failed: " + ex.Message);
		}
	}

	private void RemoveMemoryEntityDataById(string memoryId) => MemoryIdentityState.RemoveMemoryEntityDataById(memoryId);

	private void CleanupNonHeroMemoryForRemovedParty(PartyBase partyBase, MobileParty mobileParty, string reason)
	{
		try
		{
			MobileParty party = mobileParty ?? partyBase?.MobileParty;
			List<string> needles = BuildNonHeroPartyMemoryNeedles(party, partyBase);
			if (needles.Count == 0)
			{
				return;
			}
			HashSet<string> ids = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
			void AddMatchingKeys(IEnumerable<string> keys)
			{
				if (keys == null)
				{
					return;
				}
				foreach (string key in keys)
				{
					string memoryId = NormalizeMemoryHeroId(key);
					if (IsNonHeroMemoryIdForParty(memoryId, needles))
					{
						ids.Add(memoryId);
					}
				}
			}
			AddMatchingKeys(_dialogueHistory?.Keys);
			AddMatchingKeys(_dialogueHistoryStorage?.Keys);
			AddMatchingKeys(_dailyMemoryDrafts?.Keys);
			AddMatchingKeys(_dailyMemoryDraftStorage?.Keys);
			AddMatchingKeys(_compressedMemoryBlocks?.Keys);
			AddMatchingKeys(_compressedMemoryBlockStorage?.Keys);
			AddMatchingKeys(_memoryOverviewStates?.Keys);
			AddMatchingKeys(_memoryOverviewStateStorage?.Keys);
			AddMatchingKeys(_npcMajorActionSummaries?.Keys);
			AddMatchingKeys(_npcMajorActionSummaryStorage?.Keys);
			AddMatchingKeys(_npcMajorActions?.Keys);
			AddMatchingKeys(_npcMajorActionStorage?.Keys);
			AddMatchingKeys(_npcRecentActions?.Keys);
			AddMatchingKeys(_npcRecentActionStorage?.Keys);
			AddMatchingKeys((_memorySummaryQueue ?? new List<MemorySummaryJob>()).Select((MemorySummaryJob x) => x?.HeroId));
			AddMatchingKeys((_memoryOverviewQueue ?? new List<MemoryOverviewJob>()).Select((MemoryOverviewJob x) => x?.HeroId));
			AddMatchingKeys((_npcMajorActionSummaryQueue ?? new List<MajorActionSummaryJob>()).Select((MajorActionSummaryJob x) => x?.HeroId));
			AddMatchingKeys((_pendingWeeklyMemoryMaterialTriggers ?? new List<WeeklyMemoryMaterialTrigger>()).Select((WeeklyMemoryMaterialTrigger x) => x?.MemoryId));
			AddMatchingKeys(GetInteractionMemoryRecoveryProjectionSubjects());
			foreach (string id in ids.ToList())
			{
				RemoveMemoryEntityDataById(id);
			}
			LogNonHeroMemoryTrace(() => "stage=cleanup_removed_party reason=" + (reason ?? "") + " party=" + (party?.StringId ?? party?.Name?.ToString() ?? "") + " partyIndex=" + (partyBase?.Index ?? party?.Party?.Index ?? -1) + " needles=" + string.Join(",", needles) + " removed=" + ids.Count);
			if (ids.Count > 0)
			{
				Logger.Log("DialogueHistory", "cleaned destroyed non-hero party memory count=" + ids.Count + " partyIndex=" + (partyBase?.Index ?? party?.Party?.Index ?? -1) + " party=" + (party?.StringId ?? party?.Name?.ToString() ?? "") + " reason=" + (reason ?? ""));
			}
		}
		catch (Exception ex)
		{
			Logger.Log("DialogueHistory", "[WARN] clean destroyed non-hero party memory failed: " + ex.Message);
		}
	}

	private void OnMobilePartyDestroyedForNonHeroMemoryCleanup(MobileParty mobileParty, PartyBase destroyerParty)
	{
		// 清理只按本存档这一支 MobileParty 的精确 key 执行：StringId 为主，GUID/party_index 仅兼容旧 fallback。
		// 不能按名字/兵种模糊删除，否则同名劫匪、商队会互相清理并重新表现为共享记忆。
		RemoveWildernessNonHeroPartyMemory(mobileParty, mobileParty?.Party, "mobile_party_destroyed");
	}

	private void OnPartyRemovedForNonHeroMemoryCleanup(PartyBase party)
	{
		// 只删除这一支被移除部队的精确 party 记忆，避免同名队伍共享/误删。
		RemoveWildernessNonHeroPartyMemory(party?.MobileParty, party, "party_removed");
	}

	private static bool IsMemoryEntityEligibleForCompressedMemory(string memoryId)
	{
		string text = NormalizeMemoryHeroId(memoryId);
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		if (IsNonHeroMemoryId(text))
		{
			return true;
		}
		try
		{
			Hero hero = FindHeroById(text);
			return IsHeroNpcEligibleForCompressedMemory(hero);
		}
		catch
		{
			return false;
		}
	}

	private static bool IsHeroNpcEligibleForCompressedMemory(Hero hero)
	{
		// Dead and disabled Heroes remain addressable in Bannerlord's object registry, but cannot own live dialogue memory.
		return hero != null && hero.IsAlive && !hero.IsDisabled && !string.IsNullOrWhiteSpace(hero.StringId) && (Hero.MainHero == null || !object.ReferenceEquals(hero, Hero.MainHero));
	}

