	{
		if (targetAgentIndex < 0)
		{
			return "";
		}
		string text = ShoutBehavior.GetLatestSceneNpcUtteranceForExternal(targetAgentIndex);
		return string.IsNullOrWhiteSpace(text) ? "" : StripSpeakerPrefixForRecall(text);
	}

