	private string BuildHistoryContextById(string memoryId, string memoryName, int maxLines = 0, string currentInput = null, string secondaryInput = null, bool includeCurrentActiveSceneSession = false, HistoryPromptSnapshot snapshot = null)
	{
		string normalizedMemoryId = NormalizeMemoryHeroId(memoryId);
		if (snapshot == null && !IsMemoryEntityEligibleForCompressedMemory(normalizedMemoryId))
		{
			return "";
		}
		try
		{
			Stopwatch sw = Stopwatch.StartNew();
			int memoryBlockCount = snapshot?.BlockCount ?? LoadCompressedMemoryBlocksById(normalizedMemoryId).Count;
			int dailyDraftCount = snapshot?.DraftCount ?? LoadDailyMemoryDraftsById(normalizedMemoryId).Count;
			StringBuilder stringBuilder = new StringBuilder(4096);
			string memoryOverviewContext = snapshot == null ? BuildMemoryOverviewContextById(normalizedMemoryId) : snapshot.Overview;
			if (!string.IsNullOrWhiteSpace(memoryOverviewContext))
			{
				stringBuilder.AppendLine(memoryOverviewContext);
				stringBuilder.AppendLine();
			}
			string compressedMemoryContext = BuildCompressedMemoryContextById(normalizedMemoryId, currentInput, secondaryInput, snapshot);
			if (!string.IsNullOrWhiteSpace(compressedMemoryContext))
			{
				stringBuilder.AppendLine(compressedMemoryContext);
				stringBuilder.AppendLine();
			}
			string text4 = stringBuilder.ToString().TrimEnd();
			sw.Stop();
			Logger.Log("DialogueHistory", string.Format("compressed_context hero={0} chars={1} blocks={2} drafts={3}", normalizedMemoryId, text4.Length, memoryBlockCount, dailyDraftCount));
			Logger.Log("Logic", "[MemoryPerf] history_context_done hero=" + normalizedMemoryId + " blocks=" + memoryBlockCount + " drafts=" + dailyDraftCount + " overviewChars=" + ((memoryOverviewContext ?? "").Length) + " compressedChars=" + ((compressedMemoryContext ?? "").Length) + " totalChars=" + text4.Length + " npcRecall=" + (!string.IsNullOrWhiteSpace(secondaryInput)) + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			if (IsNonHeroMemoryId(normalizedMemoryId))
			{
				LogNonHeroMemoryTrace("stage=history_context_done memoryId=" + normalizedMemoryId + " blocks=" + memoryBlockCount + " drafts=" + dailyDraftCount + " overviewChars=" + ((memoryOverviewContext ?? "").Length) + " compressedChars=" + ((compressedMemoryContext ?? "").Length) + " totalChars=" + text4.Length + " npcRecall=" + (!string.IsNullOrWhiteSpace(secondaryInput)) + " includeCurrentSession=" + includeCurrentActiveSceneSession + " ms=" + Math.Round(sw.Elapsed.TotalMilliseconds, 2));
			}
			Logger.Obs("History", "build_context", new Dictionary<string, object>
			{
				["heroId"] = normalizedMemoryId,
				["memoryBlocks"] = memoryBlockCount,
				["dailyDrafts"] = dailyDraftCount,
				["npcRecall"] = !string.IsNullOrWhiteSpace(secondaryInput),
				["chars"] = text4.Length
			});
			Logger.Metric("history.build_context");
			return text4;
		}
		catch (Exception ex)
		{
			Logger.Log("DialogueHistory", "[错误] 构建上下文失败: " + ex.Message);
			Logger.Obs("History", "build_context_error", new Dictionary<string, object>
			{
				["message"] = ex.Message,
				["type"] = ex.GetType().Name
			});
			Logger.Metric("history.build_context", ok: false);
			return "";
		}
	}

