		return !string.IsNullOrWhiteSpace(effectiveApiUrl) && !string.IsNullOrWhiteSpace(apiKey) && !string.IsNullOrWhiteSpace(modelName);
	}

	private static bool TryResolveUniversalApiConfig(DuelSettings settings, UniversalApiRoute route, out string effectiveApiUrl, out string apiKey, out string modelName, out string resolvedRoute, out string errorMessage)
	{
		effectiveApiUrl = "";
		apiKey = "";
		modelName = "";
		resolvedRoute = "main";
		errorMessage = "请检查 MCM 设置。";
		bool hasAuxiliaryDedicatedFields = false;
		bool hasEventAndRebellionDedicatedFields = false;
		if (settings == null)
		{
			return false;
		}
		if (route == UniversalApiRoute.Auxiliary)
		{
			if (TryGetAuxiliaryDedicatedApiConfig(settings, out effectiveApiUrl, out apiKey, out modelName, out hasAuxiliaryDedicatedFields))
			{
				resolvedRoute = "auxiliary_dedicated";
				errorMessage = "";
				return true;
			}
		}
		if (route == UniversalApiRoute.EventAndRebellion)
		{
			if (TryGetEventAndRebellionDedicatedApiConfig(settings, out effectiveApiUrl, out apiKey, out modelName, out hasEventAndRebellionDedicatedFields))
			{
				resolvedRoute = "event_rebellion_dedicated";
				errorMessage = "";
				return true;
			}
		}
		if (TryGetPrimaryUniversalApiConfig(settings, out effectiveApiUrl, out apiKey, out modelName))
		{
			resolvedRoute = ((route == UniversalApiRoute.Auxiliary) ? (hasAuxiliaryDedicatedFields ? "auxiliary_partial_fallback_main" : "auxiliary_fallback_main") : ((route == UniversalApiRoute.EventAndRebellion) ? (hasEventAndRebellionDedicatedFields ? "event_rebellion_partial_fallback_main" : "event_rebellion_fallback_main") : "main"));
			errorMessage = "";
			return true;
		}
		return false;
	}

	private static string TrimUniversalApiRawForLog(string text, int maxChars = 3000)
	{
		text = (text ?? "").Replace("\r\n", "\n").Replace('\r', '\n').Trim();
		if (text.Length <= maxChars)
		{
			return text;
		}
		return text.Substring(0, maxChars) + "...";
	}

	private static bool LooksLikeUniversalThinkingControlError(string responseBody)
	{
		string text = (responseBody ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		bool hasThinkingField = ContainsAnyIgnoreCase(text, "thinking", "reasoning_effort", "output_config", "budget_tokens");
		bool hasUnsupportedSignal = ContainsAnyIgnoreCase(text, "unsupported", "unknown", "invalid", "unexpected", "not allowed", "not supported", "extra inputs are not permitted");
		return hasThinkingField && hasUnsupportedSignal;
	}

	private static void ResolveUniversalThinkingSettings(DuelSettings settings, string resolvedRoute, out bool thinkingEnabled, out string effort)
	{
		thinkingEnabled = true;
		effort = DuelSettings.ReasoningEffortHigh;
		if (settings == null)
		{
			return;
		}
		string route = (resolvedRoute ?? "").Trim();
		if (route.StartsWith("event_rebellion", StringComparison.OrdinalIgnoreCase))
		{
			thinkingEnabled = settings.EventAndRebellionApiThinkingEnabled;
			effort = settings.GetEventAndRebellionApiReasoningEffort();
			return;
		}
		if (route.StartsWith("auxiliary_dedicated", StringComparison.OrdinalIgnoreCase))
		{
			thinkingEnabled = settings.AuxiliaryApiThinkingEnabled;
			effort = settings.GetAuxiliaryApiReasoningEffort();
			return;
		}
		thinkingEnabled = settings.MainApiThinkingEnabled;
		effort = settings.GetMainApiReasoningEffort();
	}

	private static float ResolveUniversalApiTemperature(DuelSettings settings, string resolvedRoute)
	{
		if (settings == null)
		{
			return 0.8f;
		}
		string route = (resolvedRoute ?? "").Trim();
		if (route.StartsWith("event_rebellion_dedicated", StringComparison.OrdinalIgnoreCase))
		{
			return settings.GetEventAndRebellionApiTemperature();
		}
		if (route.StartsWith("auxiliary_dedicated", StringComparison.OrdinalIgnoreCase))
		{
			return settings.GetAuxiliaryApiTemperature();
		}
		return settings.GetMainApiTemperature();
	}

	private static int ResolveUniversalMaxTokens(DuelSettings settings, string resolvedRoute)
	{
		string route = (resolvedRoute ?? "").Trim();
		if (route.StartsWith("event_rebellion", StringComparison.OrdinalIgnoreCase))
		{
			return settings?.GetEventAndRebellionApiMaxTokens() ?? EventAndRebellionApiDefaultMaxTokens;
		}
		if (route.StartsWith("auxiliary_dedicated", StringComparison.OrdinalIgnoreCase))
		{
			return settings?.GetAuxiliaryApiMaxTokens() ?? UniversalApiDefaultMaxTokens;
		}
		return settings?.GetMainApiMaxTokens() ?? UniversalApiDefaultMaxTokens;
	}

	private static string ExtractUniversalGeminiCandidateText(JToken candidate)
	{
		try
		{
			if (candidate == null)
			{
				return "";
			}
			StringBuilder stringBuilder = new StringBuilder();
			JToken parts = candidate.SelectToken("content.parts") ?? candidate.SelectToken("delta.content.parts");
			if (parts is JArray jArray)
			{
				foreach (JToken item in jArray)
				{
					string text = item?["text"]?.ToString() ?? "";
					if (!string.IsNullOrEmpty(text))
					{
						stringBuilder.Append(text);
					}
				}
			}
			string directText = candidate.SelectToken("content.parts[0].text")?.ToString()
				?? candidate.SelectToken("delta.content.parts[0].text")?.ToString()
				?? candidate.SelectToken("output")?.ToString();
			if (stringBuilder.Length == 0 && !string.IsNullOrEmpty(directText))
			{
				stringBuilder.Append(directText);
			}
			return stringBuilder.ToString();
		}
		catch
		{
			return "";
		}
	}

	private static string ExtractUniversalStreamDelta(JObject json)
	{
		return LlmApiCompat.ExtractStreamDeltaText(json);
	}

	private static bool IsUniversalStreamNonContentChunk(JObject json)
	{
		return LlmApiCompat.IsNonContentStreamChunk(json);
	}

	private static string ExtractUniversalContentTokenText(JToken token)
	{
		if (token == null)
		{
			return "";
		}
		if (token.Type == JTokenType.String)
		{
			return token.ToString();
		}
		if (token is JArray array)
		{
			StringBuilder stringBuilder = new StringBuilder();
			foreach (JToken item in array)
			{
				string text = "";
				if (item != null)
				{
					if (item.Type == JTokenType.String)
					{
						text = item.ToString();
					}
					else
					{
						text = item["text"]?.ToString()
							?? item["content"]?.ToString()
							?? item.SelectToken("text.value")?.ToString()
							?? "";
					}
				}
				if (!string.IsNullOrEmpty(text))
				{
					stringBuilder.Append(text);
				}
			}
			return stringBuilder.ToString();
		}
		return token.ToString();
	}

	private static string ExtractUniversalNonStreamContent(JObject json)
	{
		return LlmApiCompat.ExtractAssistantText(json);
	}

	private async Task<ApiCallResult> CallWeeklyReportApiDetailed(string systemPrompt, string userPrompt)
	{
		ApiCallResult legacyResult = new ApiCallResult();
		try
		{
			DuelSettings settings = DuelSettings.GetSettings();
			if (!TryResolveUniversalApiConfig(settings, UniversalApiRoute.EventAndRebellion, out string apiUrl, out string apiKey, out string modelName, out string resolvedRoute, out string errorMessage))
			{
				legacyResult.ErrorMessage = errorMessage;
				return legacyResult;
			}
			int maxTokens = ResolveUniversalMaxTokens(settings, resolvedRoute);
			float temperature = ResolveUniversalApiTemperature(settings, resolvedRoute);
			ResolveUniversalThinkingSettings(settings, resolvedRoute, out bool thinkingEnabled, out string reasoningEffort);
			long runtimeGeneration = SaveRuntimeGuard.CaptureGeneration();
			PromptPackage prompt = new PromptPackage(
				new[]
				{
					new PromptMessage("system", systemPrompt ?? string.Empty),
					new PromptMessage("user", userPrompt ?? string.Empty)
				},
				maxTokens,
				modelName);
			LlmProviderSnapshot provider = new LlmProviderSnapshot(
				resolvedRoute,
				apiUrl,
				modelName,
				DuelSettings.LlmRequestTimeoutMilliseconds,
				maxTokens);
			TraceContext trace = new TraceContext(
				"af-weekly-report-" + DateTime.UtcNow.Ticks.ToString(CultureInfo.InvariantCulture),
				runtimeGeneration,
				runtimeGeneration,
				"weekly-report",
				#if BANNERLORD_1_4_OR_GREATER
				"1.4"
				#else
				"1.3"
				#endif
			);
			LegacyConfiguredChatGateway gateway = new LegacyConfiguredChatGateway(
				_ => apiKey,
				temperature: temperature,
				disableThinking: false,
				retryWithoutThinkingOnBadRequest: true,
				thinkingEnabled: thinkingEnabled,
				reasoningEffort: reasoningEffort);
			LlmGenerateResult generated = await gateway.GenerateAsync(
				new LlmGenerateRequest(trace, provider, prompt, InteractionStage.MainReply),
				CancellationToken.None).ConfigureAwait(false);
			if (SaveRuntimeGuard.IsStale(runtimeGeneration, "weekly_report_gateway_response"))
			{
				legacyResult.ErrorMessage = SaveRuntimeGuard.BuildStaleRequestErrorText();
				return legacyResult;
			}
			LlmGenerateMetadata metadata = generated?.Metadata ?? LlmGenerateMetadata.Empty;
			legacyResult.Success = generated?.Status == LlmResultStatus.Succeeded;
			legacyResult.Content = CleanAIResponse(generated?.RawText ?? string.Empty);
			legacyResult.ErrorMessage = generated?.ErrorCode ?? string.Empty;
			legacyResult.StatusCode = metadata.StatusCode;
			legacyResult.IsRateLimit = metadata.IsRateLimit;
			legacyResult.IsRequestsPerMinuteLimit = metadata.IsRequestsPerMinuteLimit;
			legacyResult.IsQuotaLimit = metadata.IsQuotaLimit;
			legacyResult.RetryAfterSeconds = metadata.RetryAfterSeconds;
			Logger.Log("EventWeeklyReport", "[Gateway] route=" + resolvedRoute + " status=" + (metadata.StatusCode?.ToString(CultureInfo.InvariantCulture) ?? "unknown") + " success=" + legacyResult.Success + " error=" + (legacyResult.ErrorMessage ?? ""));
			return legacyResult;
		}
		catch (Exception ex)
		{
			legacyResult.ErrorMessage = LlmRetryPrompt.BuildFailureDetail(ex.Message, legacyResult.Content, "");
			return legacyResult;
		}
	}

