	private static Settlement GetCurrentRoyalDomainConversationSettlement()
	{
		Settlement settlement = Settlement.CurrentSettlement ?? MobileParty.MainParty?.CurrentSettlement;
		if (settlement?.Town == null || settlement.OwnerClan != Clan.PlayerClan)
		{
			return null;
		}
		return settlement;
	}

	private static bool CanApplyRoyalDomainConversationLoyaltyForHero(Hero targetHero)
	{
		if (targetHero == null)
		{
			return true;
		}
		Hero mainHero = Hero.MainHero;
		Clan playerClan = Clan.PlayerClan ?? mainHero?.Clan;
		// Loyalty reflects ordinary residents: this one-shot reply check uses only O(1) Hero/Clan flags and never scans rosters.
		bool isPlayerFamilyOrCompanion = targetHero.IsPlayerCompanion
			|| (playerClan != null && (targetHero.CompanionOf == playerClan || targetHero.Clan == playerClan))
			|| RomanceSystemBehavior.IsPlayerCompanionOrFamily(targetHero);
		return PatienceRules.RoyalLoyaltyEligible(true, targetHero == mainHero, targetHero.IsPrisoner, isPlayerFamilyOrCompanion, targetHero.IsLord);
	}

	private static void ApplyRoyalDomainConversationLoyaltyFromMood(PatienceMood mood, Hero targetHero, string unnamedKey, string npcName, bool directConversation)
	{
		int num = ComputeRoyalDomainConversationLoyaltyDelta(mood);
		if (num == 0 || !CanApplyRoyalDomainConversationLoyaltyForHero(targetHero))
		{
			return;
		}
		Settlement currentRoyalDomainConversationSettlement = GetCurrentRoyalDomainConversationSettlement();
		Town town = currentRoyalDomainConversationSettlement?.Town;
		if (town == null)
		{
			return;
		}
		try
		{
			float loyalty = town.Loyalty;
			float maximumLoyaltyInSettlement = Campaign.Current?.Models?.SettlementLoyaltyModel?.MaximumLoyaltyInSettlement ?? 100f;
			town.Loyalty = MBMath.ClampFloat(town.Loyalty + (float)num, 0f, maximumLoyaltyInSettlement);
			SyncTownRebelliousStateFromCurrentLoyalty(town);
			string text = targetHero?.StringId ?? unnamedKey ?? npcName ?? "";
			AnimusForgeQuickInfo.Show(currentRoyalDomainConversationSettlement.Name.ToString() + " 忠诚度 +" + num);
			Logger.Log("Patience", $"royal_domain_conversation_loyalty settlement={currentRoyalDomainConversationSettlement.StringId} npc={text} mood={mood} loyalty={loyalty:0.##}->{town.Loyalty:0.##} delta={num}");
			Logger.Obs("Patience", "royal_domain_conversation_loyalty", new Dictionary<string, object>
			{
				["settlementId"] = currentRoyalDomainConversationSettlement.StringId ?? "",
				["npcId"] = text,
				["mood"] = mood.ToString(),
				["loyaltyBefore"] = loyalty,
				["loyaltyAfter"] = town.Loyalty,
				["loyaltyDelta"] = num,
				["directConversation"] = directConversation
			});
			Logger.Metric("patience.royal_domain_conversation_loyalty");
		}
		catch (Exception ex)
		{
			Logger.Log("Patience", "[WARN] apply royal domain conversation loyalty failed: " + ex.Message);
		}
	}

	private bool ApplyPatienceDeltaInternal(string key, int maxPatience, PatienceMood mood, out int before, out int after)
	{
		var result = _patienceOwner.Apply(key, maxPatience, GetNowCampaignDay(), mood);
		before = result.Before; after = result.After;
		return result.BecameExhausted;
	}

	private bool ApplyPatiencePostprocessMoodOverrideInternal(string key, int maxPatience, PatienceMood mood, out int before, out int after, out int delta)
	{
		var result = _patienceOwner.OverrideNeutral(key, maxPatience, GetNowCampaignDay(), mood);
		before = result.Before; after = result.After; delta = result.Delta;
		return result.BecameExhausted;
	}

	private static string BuildExhaustedReply(string npcName, int relation, int refusalCount = 1)
	{
		string text = (string.IsNullOrWhiteSpace(npcName) ? "我" : npcName);
		if (refusalCount < 1)
		{
			refusalCount = 1;
		}
		if (relation >= 40)
		{
			string[] array = new string[3]
			{
				text + "压低声音：今天我确实有些乏了，改天再聊。",
				text + "轻叹：我现在没有余力应付长谈，先到这里吧。",
				text + "摇头道：等我缓一缓，再听你说。"
			};
			return array[(refusalCount - 1) % array.Length];
		}
		if (relation <= -20)
		{
			string[] array2 = new string[3]
			{
				text + "皱眉道：我眼下有要事，没空陪你闲扯，退下。",
				text + "冷声道：军务在身，今天到此为止。",
				text + "摆手打断：我还要处理别的事，改日再说。"
			};
			return array2[(refusalCount - 1) % array2.Length];
		}
		string[] array3 = new string[3]
		{
			text + "摆摆手：我这边还有事，今天就先到这。",
			text + "皱了皱眉：行程紧，改日再谈。",
			text + "侧过身：先到这里，我得去处理别的事。"
		};
		return array3[(refusalCount - 1) % array3.Length];
	}

	private static string BuildExhaustedPatienceInstruction(bool includeRelationPenalty)
	{
		string text = BuildPlayerPublicDisplayNameForPrompt();
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "玩家";
		}
		if (!includeRelationPenalty)
		{
			return "耐心已归零：本轮优先用军务在身、行程紧、需要离开、精神疲惫或另有要事等理由，给出委婉的回避式回复，尽量收束或回避当前话题；若" + text + "继续追问，仍可继续回应，但语气应明显更谨慎或更不耐烦，不要直说系统规则或数值。";
		}
		return "耐心已归零：本轮优先用军务在身、行程紧、需要离开、精神疲惫或另有要事等理由，给出委婉的回避式回复，尽量收束或回避当前话题；若" + text + "继续追问，仍可继续回应，但语气应明显更谨慎或更不耐烦，系统会额外降低你与" + text + "的关系，不要直说系统规则或数值。";
	}

	private static string BuildPatiencePromptText(PatienceSnapshot snap, bool includeClanRelation = true)
	{
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine(includeClanRelation ? "【4.四值状态】" : "【4.三值状态】");
		stringBuilder.AppendLine(BuildCompactStateLine(snap, includeClanRelation));
		stringBuilder.AppendLine("【NPC耐心状态】");
		if (snap.Current <= 0.01f)
		{
			stringBuilder.AppendLine(BuildExhaustedPatienceInstruction(includeRelationPenalty: true));
		}
		else
		{
			stringBuilder.AppendLine("耐心越低，语气越不耐烦；若耐心耗尽，应优先给出委婉的回避式回复。");
		}
		return stringBuilder.ToString();
	}

	private string BuildDirectPatiencePrompt(Hero targetHero, out bool exhausted, out string exhaustedReply)
	{
		exhausted = false;
		exhaustedReply = "";
		if (targetHero == null)
		{
			return "";
		}
		PatienceSnapshot heroPatienceSnapshot = GetHeroPatienceSnapshot(targetHero);
		bool includeClanRelation = !ShouldOmitClanRelationFromPrompt(targetHero);
		if (heroPatienceSnapshot.Current <= 0.01f)
		{
			return BuildPatiencePromptText(heroPatienceSnapshot, includeClanRelation);
		}
		return BuildPatiencePromptText(heroPatienceSnapshot, includeClanRelation);
	}

	private void ApplyPatienceFromHeroResponse(Hero targetHero, ref string aiResponse, bool directConversation)
	{
		if (targetHero == null)
		{
			string text = aiResponse ?? "";
			ExtractMoodAndStripTag(ref text);
			aiResponse = text;
			return;
		}
		PatienceSnapshot heroPatienceSnapshot = GetHeroPatienceSnapshot(targetHero);
		PatienceMood patienceMood = ExtractMoodAndStripTag(ref aiResponse);
		int before;
		int after;
		bool flag = ApplyPatienceDeltaInternal(heroPatienceSnapshot.Key, heroPatienceSnapshot.Max, patienceMood, out before, out after);
		int relation = heroPatienceSnapshot.Relation;
		int privateLove = heroPatienceSnapshot.PrivateLove;
		int num = PatienceRules.HeroRelationEffect(patienceMood, relation, before, correction: false);
		int num2 = ComputePrivateLoveDelta(patienceMood);
		bool flag2 = before <= 0;
		int num3 = relation;
		if (num != 0)
		{
			try
			{
				if (Hero.MainHero != null && targetHero != null)
				{
					if (RomanceSystemBehavior.TryGetPrivateLoveAsPlayerRelation(targetHero, out var _))
					{
						RomanceSystemBehavior.Instance?.AdjustPrivateLove(targetHero, num, "mood_tag_relation_delta");
					}
					else
					{
						ChangeRelationAction.ApplyRelationChangeBetweenHeroes(Hero.MainHero, targetHero, num);
					}
					num3 = GetRelationWithPlayerSafe(targetHero);
				}
			}
			catch (Exception ex)
			{
				Logger.Log("Patience", "[WARN] apply relation delta failed: " + ex.Message);
			}
		}
		if (num2 != 0)
		{
			RomanceSystemBehavior.Instance?.AdjustPrivateLove(targetHero, num2, "mood_tag");
		}
		int num4 = RomanceSystemBehavior.Instance?.GetPrivateLove(targetHero) ?? privateLove;
		try
		{
			Logger.Log("Patience", $"hero={targetHero.StringId} mood={patienceMood} value={before}->{after}/{heroPatienceSnapshot.Max} relation={relation}->{num3} delta={num} privateLove={privateLove}->{num4} deltaLove={num2}");
			Logger.Obs("Patience", "hero_update", new Dictionary<string, object>
			{
				["heroId"] = targetHero.StringId ?? "",
				["mood"] = patienceMood.ToString(),
				["patienceBefore"] = before,
				["patienceAfter"] = after,
				["patienceMax"] = heroPatienceSnapshot.Max,
				["relationBefore"] = relation,
				["relationAfter"] = num3,
				["relationDelta"] = num,
				["privateLoveBefore"] = privateLove,
				["privateLoveAfter"] = num4,
				["privateLoveDelta"] = num2,
				["continuedAtZero"] = flag2,
				["directConversation"] = directConversation
			});
			Logger.Metric("patience.hero_update");
		}
		catch
		{
		}
		if (!flag)
		{
			return;
		}
		try
		{
			Logger.Log("Patience", "hero=" + targetHero.StringId + " reached_zero=true defer_exhausted_to_next_round=" + (directConversation ? "direct" : "scene"));
		}
		catch
		{
		}
	}

