		stringBuilder.AppendLine("[BATCH]");
		stringBuilder.AppendLine("batch_mode=" + (((batch?.OutputMode ?? WeeklyReportOutputMode.FullReport) == WeeklyReportOutputMode.TitleShortTagsOnly) ? "title_short_tags_only" : "full_report"));
		stringBuilder.AppendLine("week_index=" + ((batch != null) ? batch.WeekIndex : 0));
		stringBuilder.AppendLine("day_range=" + ((batch != null) ? batch.StartDay : 0) + "-" + ((batch != null) ? batch.EndDay : 0));
		stringBuilder.AppendLine("block_count=" + list.Count);
		foreach (WeeklyEventMaterialPreviewGroup item in list)
		{
			stringBuilder.AppendLine();
			stringBuilder.AppendLine(BuildWeeklyBatchPromptInputBlock(item, (batch != null) ? batch.WeekIndex : 0));
		}
		return stringBuilder.ToString().TrimEnd();
	}

	private string BuildWeeklyBatchPromptInputBlock(WeeklyEventMaterialPreviewGroup group, int weekIndex)
	{
		bool flag = string.Equals((group?.GroupKind ?? "").Trim(), "world", StringComparison.OrdinalIgnoreCase);
		bool flag2 = (group?.OutputMode ?? WeeklyReportOutputMode.FullReport) == WeeklyReportOutputMode.TitleShortTagsOnly;
		StringBuilder stringBuilder = new StringBuilder();
		stringBuilder.AppendLine(flag ? "[WORLD_BLOCK]" : "[KINGDOM_BLOCK]");
		stringBuilder.AppendLine("report_id=" + BuildWeeklyReportGroupReportId(group));
		stringBuilder.AppendLine("mode=" + (flag2 ? "title_short_tags_only" : "full_report"));
		stringBuilder.AppendLine("kind=" + (flag ? "world" : "kingdom"));
		if (!flag)
		{
			stringBuilder.AppendLine("kingdom_id=" + ((group?.KingdomId ?? "").Trim()));
			stringBuilder.AppendLine("kingdom_name=" + ResolveKingdomDisplay(group?.KingdomId));
			string weeklyReportCurrentKingdomStabilityTierText = BuildWeeklyReportCurrentKingdomStabilityTierText(group);
			if (!string.IsNullOrWhiteSpace(weeklyReportCurrentKingdomStabilityTierText))
			{
				stringBuilder.AppendLine("stability=" + weeklyReportCurrentKingdomStabilityTierText.Replace("当前王国稳定度评级：", "").Trim());
			}
		}
		stringBuilder.AppendLine("title_hint=" + BuildDefaultWeeklyReportTitle(group, weekIndex));
		if (!flag2 && (group?.IncludePreviousReportInPrompt ?? true))
		{
			stringBuilder.AppendLine("previous_report_note=上一周短摘要只用于连续性参考，禁止复用上一周标题或正文；本周内容必须依据 materials。");
			stringBuilder.AppendLine("previous_report=");
			stringBuilder.AppendLine(GetPreviousWeeklyReportText(group, weekIndex));
		}
		stringBuilder.AppendLine("materials=");
		stringBuilder.AppendLine(BuildWeeklyReportPromptMaterialLines(group));
		return stringBuilder.ToString().TrimEnd();
	}

	private static string BuildWeeklyReportPromptMaterialLines(WeeklyEventMaterialPreviewGroup group)
	{
		List<EventMaterialReference> list = (group?.PromptMaterials != null && group.PromptMaterials.Count > 0) ? group.PromptMaterials : group?.Materials;
		return AnnotateWeeklyReportRulerInMaterialText(BuildWeeklyReportMaterialLines(list), group);
	}

	private static string AnnotateWeeklyReportRulerInMaterialText(string materialText, WeeklyEventMaterialPreviewGroup group)
	{
		if (!string.Equals((group?.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase))
		{
			return materialText ?? "";
		}
		string text = (materialText ?? "").TrimEnd();
		if (string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		if (HasWeeklyReportRulerContextMaterial(group))
		{
			return text;
		}
		Kingdom kingdom = FindKingdomById(group?.KingdomId);
		Hero ruler = kingdom?.Leader ?? kingdom?.RulingClan?.Leader;
		string rulerName = GetHeroDisplayName(ruler);
		if (ruler == null || string.IsNullOrWhiteSpace(rulerName) || string.Equals(rulerName, "某位领主", StringComparison.OrdinalIgnoreCase) || rulerName.Trim().Length < 2)
		{
			return text;
		}
		return AnnotateWeeklyReportRulerNameInText(text, rulerName.Trim());
	}

	private static bool HasWeeklyReportRulerContextMaterial(WeeklyEventMaterialPreviewGroup group)
	{
		return HasWeeklyReportRulerContextMaterial(group?.PromptMaterials) || HasWeeklyReportRulerContextMaterial(group?.Materials);
	}

	private static bool HasWeeklyReportRulerContextMaterial(IEnumerable<EventMaterialReference> materials)
	{
		return (materials ?? Enumerable.Empty<EventMaterialReference>()).Any((EventMaterialReference x) => string.Equals((x?.MaterialType ?? "").Trim(), "kingdom_current_ruler", StringComparison.OrdinalIgnoreCase));
	}

	private static string AnnotateWeeklyReportRulerNameInText(string text, string rulerName)
	{
		string source = text ?? "";
		string name = (rulerName ?? "").Trim();
		if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(name))
		{
			return source;
		}
		string escapedName = Regex.Escape(name);
		string annotatedExistingSuffix = Regex.Replace(source, escapedName + "(?<suffix>[\\(（][^\\r\\n\\)）]{0,120}[\\)）])", delegate(Match match)
		{
			string suffix = match.Groups["suffix"]?.Value ?? "";
			if (suffix.IndexOf("统治者", StringComparison.OrdinalIgnoreCase) >= 0)
			{
				return match.Value;
			}
			bool fullWidth = suffix.StartsWith("（", StringComparison.Ordinal);
			string open = fullWidth ? "（" : "(";
			string close = fullWidth ? "）" : ")";
			string separator = fullWidth ? "；" : ";";
			string inner = suffix.Length >= 2 ? suffix.Substring(1, suffix.Length - 2).Trim() : "";
			return name + open + (string.IsNullOrWhiteSpace(inner) ? "统治者" : ("统治者" + separator + inner)) + close;
		}, RegexOptions.CultureInvariant);
		return Regex.Replace(annotatedExistingSuffix, escapedName + "(?![\\(（])", match => name + "(统治者)", RegexOptions.CultureInvariant);
	}


