	private static string BuildDefaultWeeklyReportTitle(WeeklyEventMaterialPreviewGroup group, int weekIndex)
	{
		string text = BuildWeeklyEpicWeekLabel(weekIndex);
		if (string.Equals((group?.GroupKind ?? "").Trim(), "world", StringComparison.OrdinalIgnoreCase))
		{
			return text + "世界周报";
		}
		string text2 = ResolveKingdomDisplay(group?.KingdomId);
		if (string.IsNullOrWhiteSpace(text2))
		{
			text2 = "某王国";
		}
		return text2 + text + "周报";
	}

	private static string BuildWeeklyEpicWeekLabel(int weekIndex)
	{
		if (weekIndex <= 0)
		{
			return "第0周";
		}
		const int num = 7;
		const int num2 = 21;
		const int num3 = 84;
		int num4 = Math.Max(0, (weekIndex - 1) * num);
		int num5 = num4 / num3;
		int num6 = num4 % num3;
		int seasonIndexZeroBased = num6 / num2;
		int num7 = Math.Min(3, num6 % num2 / num + 1);
		string seasonTextZhForPrompt = GetSeasonTextZhForPrompt(seasonIndexZeroBased);
		return num5 + "年" + seasonTextZhForPrompt + "季" + ConvertWeekNumberToChineseOrdinal(num7) + "周";
	}

	private static string ConvertWeekNumberToChineseOrdinal(int weekNumber)
	{
		switch (weekNumber)
		{
		case 1:
			return "第一";
		case 2:
			return "第二";
		case 3:
			return "第三";
		case 4:
			return "第四";
		case 5:
			return "第五";
		case 6:
			return "第六";
		case 7:
			return "第七";
		case 8:
			return "第八";
		case 9:
			return "第九";
		case 10:
			return "第十";
		default:
			return "第" + Math.Max(1, weekNumber);
		}
	}

	private void ApplyWeeklyReportStabilityDelta(WeeklyEventMaterialPreviewGroup group, string eventId, string tagText)
	{
		if (_weeklyReportAppliedStabilityDeltas == null)
		{
			_weeklyReportAppliedStabilityDeltas = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
		}
		if (!DuelSettings.IsKingdomStabilityAndRebellionEnabled())
		{
			return;
		}
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return;
		}
		int value = 0;
		_weeklyReportAppliedStabilityDeltas.TryGetValue(text, out value);
		int num = 0;
		Kingdom kingdom = null;
		if (string.Equals((group?.GroupKind ?? "").Trim(), "kingdom", StringComparison.OrdinalIgnoreCase))
		{
			kingdom = FindKingdomById(group?.KingdomId);
			if (kingdom != null)
			{
				num = ExtractWeeklyReportStabilityDelta(tagText);
			}
		}
		if (num == value)
		{
			return;
		}
		if (kingdom == null)
		{
			return;
		}
		KingdomStability.ApplyWeeklyDelta(text, GetKingdomStabilityValue(kingdom), num,
			updated => SetKingdomStabilityValue(kingdom, updated));
	}

	private void UpsertWeeklyReportEventRecord(WeeklyEventMaterialPreviewGroup group, int weekIndex, string title, string shortSummary, string report, string tagText, string promptText, bool sanitizeAfter = true)
	{
		List<EventMaterialReference> materials = OrderWeeklyPreviewMaterials(group?.Materials).Where((EventMaterialReference x) => x != null).Select(CloneEventMaterialReference).ToList();
		UpsertWeeklyReportEventRecord(group, weekIndex, title, shortSummary, report, tagText, promptText, materials, sanitizeAfter);
	}


