	private void MarkWeeklyReportNoticeRead(string eventId) => _weeklyNoticeOwner.MarkRead(eventId);

	internal bool OpenWeeklyReportNoticeFromMap(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text))
		{
			return false;
		}
		EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(text);
		if (eventRecordEntry == null)
		{
			InformationManager.DisplayMessage(new InformationMessage("这条周报记录已经不存在。"));
			MarkWeeklyReportNoticeRead(text);
			return true;
		}
		bool hasFullReport = !string.IsNullOrWhiteSpace(eventRecordEntry.Summary);
		// Bulletins have no three-section chronicle body; they render as a single column.
		bool isBulletin = IsWorldBulletinEventId(text);
		if (isBulletin && hasFullReport && TryShowWorldBulletinPanel(eventRecordEntry, text))
		{
			MarkWeeklyReportNoticeRead(text);
			return true;
		}
		string bodyText = BuildWeeklyReportPopupBodyText(eventRecordEntry);
		bool flag = DevWeeklyReportPopup.Show(BuildWeeklyReportNoticeTitle(eventRecordEntry), BuildWeeklyReportPopupSubtitle(eventRecordEntry), bodyText, null, "", useChronicleColumns: hasFullReport && !isBulletin, useShortReportLayout: !hasFullReport, showCloseButton: false, minimumDwellSeconds: 10.0, onMinimumDwellMet: delegate
		{
			TryAwardWeeklyReportReadingXp(text);
		});
		if (flag)
		{
			MarkWeeklyReportNoticeRead(text);
		}
		else
		{
			InformationManager.DisplayMessage(new InformationMessage("打开周报失败。"));
		}
		return flag;
	}

	private void TryAwardWeeklyReportReadingXp(string eventId)
	{
		string text = (eventId ?? "").Trim();
		if (string.IsNullOrWhiteSpace(text) || !text.StartsWith("weekly_report:", StringComparison.OrdinalIgnoreCase))
		{
			return;
		}
		if (_weeklyReportReadingXpClaimedEventIds == null)
		{
			_weeklyReportReadingXpClaimedEventIds = new List<string>();
		}
		if (_weeklyReportReadingXpClaimedEventIds.Any((string x) => string.Equals((x ?? "").Trim(), text, StringComparison.OrdinalIgnoreCase)))
		{
			return;
		}
		DuelSettings settings = DuelSettings.GetSettings();
		if (settings == null || !settings.EnableWeeklyReportReadingXpReward)
		{
			return;
		}
		int xpPerHundred = Math.Max(0, Math.Min(100, settings.WeeklyReportReadingXpPerHundredChars));
		int skillCap = Math.Max(0, Math.Min(500, settings.WeeklyReportReadingXpSkillCap));
		if (xpPerHundred <= 0 || skillCap <= 0)
		{
			return;
		}
		Hero mainHero = Hero.MainHero;
		if (mainHero == null)
		{
			return;
		}
		if (!CanAwardWeeklyReportReadingXp(mainHero, out string ineligibleReason))
		{
			Logger.Log("EventWeeklyReport", "[ReadingXp] skipped eventId=" + text + " reason=" + ineligibleReason);
			return;
		}
		EventRecordEntry eventRecordEntry = FindWeeklyReportRecordById(text);
		if (eventRecordEntry == null)
		{
			return;
		}
		string bodyText = BuildWeeklyReportPopupBodyText(eventRecordEntry);
		WeeklyReportSectionSplit split = WeeklyReportTextHelper.SplitChronicleBody(bodyText);
		int leadershipXp;
		int charmXp;
		int stewardXp;
		if (split.HasExplicitSections)
		{
			leadershipXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.MilitaryEventsText), xpPerHundred, skillCap);
			charmXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.DiplomaticAffairsText), xpPerHundred, skillCap);
			stewardXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.DomesticRealmText), xpPerHundred, skillCap);
		}
		else
		{
			int sharedXp = CalculateWeeklyReportReadingXp(WeeklyReportTextHelper.CountMeaningfulUnits(split.NormalizedBodyText), xpPerHundred, skillCap);
			// Bulletins have no chronicle sections and publish every few days: one body's worth of XP is split
			// across the three skills instead of being granted to each, so their total matches a sectioned report.
			if (IsWorldBulletinEventId(text))
			{
				sharedXp = (sharedXp + 2) / 3;
			}
			leadershipXp = sharedXp;
			charmXp = sharedXp;
			stewardXp = sharedXp;
		}
		if (leadershipXp <= 0 && charmXp <= 0 && stewardXp <= 0)
		{
			return;
		}
		_weeklyReportReadingXpClaimedEventIds.Add(text);
		NormalizeWeeklyReportReadingXpPendingBatch();
		_weeklyReportReadingXpPendingCount++;
		_weeklyReportReadingXpPendingCharm += charmXp;
		_weeklyReportReadingXpPendingLeadership += leadershipXp;
		_weeklyReportReadingXpPendingSteward += stewardXp;
		Logger.Log("EventWeeklyReport", "[ReadingXp] accumulated eventId=" + text + " pending_count=" + _weeklyReportReadingXpPendingCount + "/" + WeeklyReportReadingXpBatchSize + " charm+=" + charmXp + " leadership+=" + leadershipXp + " steward+=" + stewardXp + " pending_charm=" + _weeklyReportReadingXpPendingCharm + " pending_leadership=" + _weeklyReportReadingXpPendingLeadership + " pending_steward=" + _weeklyReportReadingXpPendingSteward + " per100=" + xpPerHundred + " cap=" + skillCap);
		if (_weeklyReportReadingXpPendingCount < WeeklyReportReadingXpBatchSize)
		{
			return;
		}
		int batchCount = _weeklyReportReadingXpPendingCount;
		int batchCharm = _weeklyReportReadingXpPendingCharm;
		int batchLeadership = _weeklyReportReadingXpPendingLeadership;
		int batchSteward = _weeklyReportReadingXpPendingSteward;
		if (!TryAwardWeeklyReportReadingXpBatch(mainHero, batchLeadership, batchCharm, batchSteward, out string awardFailureReason))
		{
			Logger.Log("EventWeeklyReport", "[ReadingXp][WARN] batch_award_failed count=" + batchCount + " charm=" + batchCharm + " leadership=" + batchLeadership + " steward=" + batchSteward + " reason=" + awardFailureReason);
			return;
		}
		_weeklyReportReadingXpPendingCount = 0;
		_weeklyReportReadingXpPendingCharm = 0;
		_weeklyReportReadingXpPendingLeadership = 0;
		_weeklyReportReadingXpPendingSteward = 0;
		InformationManager.DisplayMessage(new InformationMessage("周报研读突破：累计研读 " + batchCount + " 篇，魅力 +" + batchCharm + "，统御 +" + batchLeadership + "，管理 +" + batchSteward + "。"));
		Logger.Log("EventWeeklyReport", "[ReadingXp] batch_awarded count=" + batchCount + " charm=" + batchCharm + " leadership=" + batchLeadership + " steward=" + batchSteward);
	}

	private static bool CanAwardWeeklyReportReadingXp(Hero hero, out string reason)
	{
		reason = "";
		if (hero == null)
		{
			reason = "hero_null";
			return false;
		}
		if (hero.HeroDeveloper == null)
		{
			reason = "hero_developer_null";
			return false;
		}
		try
		{
			if (hero.IsChild)
			{
				reason = "main_hero_under_age age=" + Math.Round(hero.Age, 2);
				return false;
			}
		}
		catch (Exception ex)
		{
			reason = "age_check_failed " + ex.Message;
			return false;
		}
		return true;
	}

	private static bool TryAwardWeeklyReportReadingXpBatch(Hero hero, int leadershipXp, int charmXp, int stewardXp, out string failureReason)
	{
		failureReason = "";
		if (!CanAwardWeeklyReportReadingXp(hero, out failureReason))
		{
			return false;
		}
		try
		{
			if (leadershipXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Leadership, leadershipXp);
			}
			if (charmXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Charm, charmXp);
			}
			if (stewardXp > 0)
			{
				hero.AddSkillXp(DefaultSkills.Steward, stewardXp);
			}
			return true;
		}
		catch (Exception ex)
		{
			failureReason = ex.GetType().Name + ": " + ex.Message;
			return false;
		}
	}

	private void NormalizeWeeklyReportReadingXpPendingBatch() => _weeklyNoticeOwner.NormalizeReadingXpPendingBatch();

	private static int CalculateWeeklyReportReadingXp(int meaningfulUnitCount, int xpPerHundred, int skillCap)
	{
		if (meaningfulUnitCount <= 0 || xpPerHundred <= 0 || skillCap <= 0)
		{
			return 0;
		}
		int xp = (int)Math.Round((double)meaningfulUnitCount * xpPerHundred / 100.0, MidpointRounding.AwayFromZero);
		return Math.Max(0, Math.Min(skillCap, xp));
	}

	private static string BuildWeeklyReportNoticeTitle(EventRecordEntry entry)
	{
		string text = (entry?.Title ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		return BuildWeeklyReportBrowserDefaultTitle(entry?.EventKind, entry?.ScopeKingdomId, entry?.WeekIndex ?? 0);
	}

	private static string BuildWeeklyReportPopupBodyText(EventRecordEntry entry)
	{
		if (entry == null)
		{
			return "当前周报正文为空。";
		}
		string text = (entry.Summary ?? "").Trim();
		if (!string.IsNullOrWhiteSpace(text))
		{
			return text;
		}
		text = (entry.ShortSummary ?? "").Trim();
		return string.IsNullOrWhiteSpace(text) ? "当前周报正文为空。" : text;
	}

	private static string BuildWeeklyReportPopupSubtitle(EventRecordEntry entry)
	{
		if (entry == null)
		{
			return "";
		}
		if (IsWorldBulletinEventId(entry.EventId))
		{
			string date = (entry.CreatedDate ?? "").Trim();
			return date.Length > 0 ? "时事快报 · " + date : "时事快报";
		}
		string text = string.Equals((entry.EventKind ?? "").Trim(), "world", StringComparison.OrdinalIgnoreCase) ? "世界周报" : ResolveKingdomDisplay(entry.ScopeKingdomId);
		if (string.IsNullOrWhiteSpace(text))
		{
			text = "王国周报";
		}
		return text + " · " + BuildWeeklyEpicWeekLabel(entry.WeekIndex);
	}

	private static string BuildWeeklyReportNoticeDescription(EventRecordEntry entry)
	{
		string text = BuildWeeklyReportPopupSubtitle(entry);
		return string.IsNullOrWhiteSpace(text) ? "点击查看当前周报。" : ("点击查看：" + text);
	}



