	private static DailyMemoryLine FindDevDailyMemoryLine(List<DailyMemoryDraft> drafts, int dayIndex, int lineIndex)
	{
		DailyMemoryDraft draft = FindDevDailyMemoryDraft(drafts, dayIndex);
		if (draft?.Lines == null || lineIndex < 0 || lineIndex >= draft.Lines.Count)
		{
			return null;
		}
		return draft.Lines[lineIndex];
	}









































































